-- Korean as an app language: profiles may store it, and the catalog gets Korean names and
-- instructions (installed apps pick them up with the next catalog refresh via updated_at).
-- Legal documents stay without a Korean version; the app shows the English ones.

alter table public.profiles drop constraint profiles_language_check;
alter table public.profiles
  add constraint profiles_language_check check (language in ('en', 'de', 'pt-PT', 'pt-BR', 'ko'));

update public.equipment e set name = e.name || jsonb_build_object('ko', v.name)
from (values
  ('dumbbell', '덤벨'),
  ('barbell', '바벨'),
  ('rack', '스쿼트 랙'),
  ('bench', '벤치'),
  ('pull-up-bar', '풀업 바'),
  ('dip-bars', '딥스 바'),
  ('kettlebell', '케틀벨'),
  ('machine', '머신'),
  ('cable', '케이블'),
  ('box', '박스 / 스텝'),
  ('decline-bench', '디클라인 벤치'),
  ('ez-bar', 'EZ 바'),
  ('trap-bar', '트랩 바'),
  ('landmine', '랜드마인'),
  ('preacher-bench', '프리처 벤치'),
  ('platform', '리프팅 플랫폼'),
  ('ab-wheel', '복근 롤러'),
  ('jump-rope', '줄넘기'),
  ('safety-bar', '세이프티 스쿼트 바'),
  ('bodyweight', '맨몸'),
  ('smith-machine', '스미스 머신'),
  ('leg-curl-extension', '레그 익스텐션 / 컬')
) as v (id, name)
where e.id = v.id;

-- Korean names and how-to steps for the 231 catalog exercises, merged into the existing
-- languages.
update public.exercises e
set name = e.name || jsonb_build_object('ko', v.value -> 'name'),
  instructions = e.instructions || jsonb_build_object('ko', v.value -> 'instructions')
from jsonb_each($ko${
  "bench-press": {"name": "벤치 프레스", "instructions": [{"title": "준비", "text": "벤치에 누워 눈이 바 바로 아래에 오게 해요. 견갑골을 모으고 발을 바닥에 단단히 디뎌요."}, {"title": "내리기", "text": "바를 랙에서 빼고 가슴 아래쪽까지 컨트롤하며 내려요. 팔꿈치는 몸통에서 약 45° 벌려요."}, {"title": "밀기", "text": "팔이 거의 펴질 때까지 바를 위로, 살짝 뒤쪽으로 밀어 올려요. 엉덩이는 벤치에 붙여 두세요."}]},
  "close-grip-bench-press": {"name": "클로즈 그립 벤치 프레스", "instructions": [{"title": "준비", "text": "벤치에 누워 눈이 바 바로 아래에 오게 하고, 어깨너비 정도로 바를 잡아요. 견갑골을 모으고 발을 바닥에 단단히 디뎌요."}, {"title": "내리기", "text": "바를 랙에서 빼고 가슴 아래쪽까지 컨트롤하며 내려요. 팔꿈치는 옆구리에 가깝게 붙여요."}, {"title": "밀기", "text": "팔이 펴질 때까지 바를 다시 밀어 올려요. 손목이 팔꿈치 바로 위에 오게 유지해요."}]},
  "incline-dumbbell-press": {"name": "인클라인 덤벨 프레스", "instructions": [{"title": "벤치 조절", "text": "등받이를 30~45°로 맞춰요. 덤벨을 허벅지 위에 올리고 앉아요."}, {"title": "시작 자세", "text": "뒤로 누우면서 덤벨을 가슴 위로 밀어 올려요. 견갑골은 뒤로 모아 내리고, 발은 바닥에 단단히 디뎌요."}, {"title": "내리기", "text": "덤벨을 가슴 높이까지 천천히 내려요. 팔꿈치는 몸통에서 약 45° 벌어지게 해요."}, {"title": "밀기", "text": "팔이 거의 펴질 때까지 덤벨을 힘차게 밀어 올려요. 위에서 잠깐 멈춰요."}]},
  "dumbbell-shoulder-press": {"name": "덤벨 숄더 프레스", "instructions": [{"title": "힘주기", "text": "덤벨을 어깨 높이로 들고 손목이 팔꿈치 바로 위에 오게 해요. 코어와 엉덩이에 힘을 줘요."}, {"title": "밀기", "text": "팔이 머리 위로 완전히 펴질 때까지 곧게 밀어 올리고, 머리는 살짝 뒤로 빼요."}, {"title": "내리기", "text": "허리를 젖히지 않고 덤벨을 어깨 높이까지 컨트롤하며 내려요."}]},
  "seated-shoulder-press": {"name": "머신 숄더 프레스", "instructions": [{"title": "준비", "text": "손잡이가 어깨 높이나 그보다 살짝 아래에 오도록 시트를 조절해요. 등을 패드에 붙이고 앉아요."}, {"title": "밀기", "text": "팔이 거의 펴질 때까지 손잡이를 밀어 올려요. 어깨를 으쓱하거나 등을 패드에서 띄우지 마세요."}, {"title": "내리기", "text": "손잡이를 어깨 높이까지 천천히 내리고, 무게추가 내려앉기 직전에 멈춰요."}]},
  "arnold-press": {"name": "아놀드 프레스", "instructions": [{"title": "시작 자세", "text": "앉거나 선 자세로 덤벨을 어깨 앞에 들어요. 손바닥은 몸 쪽을 향하게 하고 팔꿈치는 몸 앞에 둬요."}, {"title": "돌리며 밀기", "text": "손바닥을 바깥쪽으로 돌리며 밀어 올려, 팔이 머리 위로 완전히 펴질 때 손바닥이 앞을 향하게 해요."}, {"title": "내리기", "text": "동작을 천천히 거꾸로 하며, 덤벨이 어깨 앞으로 돌아올 때 손바닥을 다시 몸 쪽으로 돌려요."}]},
  "lateral-raise": {"name": "사이드 레터럴 레이즈", "instructions": [{"title": "시작 자세", "text": "덤벨을 몸 옆에 들고 바르게 서서 팔꿈치를 살짝 굽혀요."}, {"title": "올리기", "text": "팔꿈치가 먼저 올라가게 하며 덤벨을 어깨 높이까지 들어 올려요. 반동을 쓰거나 어깨를 으쓱하지 마세요."}, {"title": "내리기", "text": "2~3초에 걸쳐 천천히 내리고, 아래에서도 긴장을 유지해요."}]},
  "front-raise": {"name": "프론트 레이즈", "instructions": [{"title": "시작 자세", "text": "덤벨을 허벅지 앞에 들고 바르게 서요. 손바닥은 몸 쪽을 향하게 하고 팔꿈치는 살짝 굽혀요."}, {"title": "올리기", "text": "덤벨을 몸 앞으로 곧게 어깨 높이까지 들어 올려요. 상체는 고정하고 반동을 쓰지 마세요."}, {"title": "내리기", "text": "덤벨이 다시 허벅지 앞에 올 때까지 2~3초에 걸쳐 천천히 내려요."}]},
  "reverse-fly": {"name": "리버스 플라이", "instructions": [{"title": "준비", "text": "등을 곧게 편 채 상체가 바닥과 거의 평행이 될 때까지 고관절을 접어요. 덤벨은 가슴 아래로 늘어뜨려요."}, {"title": "올리기", "text": "팔꿈치를 살짝 굽힌 채 팔이 어깨와 일직선이 될 때까지 덤벨을 옆으로 들어 올려요. 반동을 쓰지 마세요."}, {"title": "내리기", "text": "등을 굽히거나 상체를 일으키지 않고 덤벨을 가슴 아래로 천천히 내려요."}]},
  "upright-row": {"name": "업라이트 로우", "instructions": [{"title": "그립 잡기", "text": "어깨너비 정도로 바를 잡고 팔을 길게 늘어뜨려요."}, {"title": "당기기", "text": "팔꿈치가 먼저 올라가게 하며 바를 가슴 아래쪽 높이까지 당겨 올려요. 팔꿈치는 항상 손보다 높게 유지해요."}, {"title": "내리기", "text": "바를 컨트롤하며 내려요. 어깨가 끼이는 느낌이 들면 더 일찍 멈춰요."}]},
  "face-pull": {"name": "페이스 풀", "instructions": [{"title": "준비", "text": "케이블을 가슴 위쪽과 얼굴 사이 높이에 맞추고 로프를 연결해요. 엄지가 뒤를 향하게 로프 끝을 잡고 뒤로 물러서요."}, {"title": "당기기", "text": "로프를 얼굴 쪽으로 당기면서 양 끝을 벌려, 손이 귀 옆에 오게 해요. 팔꿈치는 높게 유지해요."}, {"title": "되돌리기", "text": "잠깐 멈춰 후면 삼각근을 조인 다음, 팔이 펴질 때까지 로프를 천천히 되돌려요."}]},
  "cable-crossover": {"name": "케이블 크로스오버", "instructions": [{"title": "준비", "text": "케이블을 높은 위치에 맞추고 양손에 손잡이를 하나씩 잡은 뒤, 한 발 앞으로 내디뎌 다리를 앞뒤로 벌리고 서요."}, {"title": "모으기", "text": "팔꿈치를 부드럽게 굽힌 채 손을 아래로 쓸어내리며 가슴 앞에서 모아요."}, {"title": "벌리기", "text": "가슴이 늘어나는 느낌이 들 때까지 팔을 천천히 벌려요."}]},
  "dip": {"name": "딥스", "instructions": [{"title": "지지 자세", "text": "팔을 곧게 펴서 평행봉 위로 몸을 밀어 올려요. 어깨는 내려서 귀에서 멀어지게 해요."}, {"title": "내리기", "text": "상체를 살짝 앞으로 기울이고 위팔이 바닥과 거의 평행이 될 때까지 내려가요."}, {"title": "밀기", "text": "다리를 흔들지 않고 팔이 완전히 펴질 때까지 다시 밀어 올려요."}]},
  "push-up": {"name": "푸시업", "instructions": [{"title": "플랭크 자세", "text": "손은 어깨보다 살짝 넓게 짚고, 머리부터 발뒤꿈치까지 몸을 일직선으로 만들어요."}, {"title": "내리기", "text": "팔꿈치를 몸통에서 약 45° 벌린 채 가슴을 바닥 쪽으로 내려요."}, {"title": "밀기", "text": "팔이 펴질 때까지 바닥을 밀어내요. 엉덩이가 처지지 않게 해요."}]},
  "triceps-pushdown": {"name": "케이블 푸시다운", "instructions": [{"title": "준비", "text": "높은 위치의 케이블에 스트레이트 바를 연결해요. 어깨너비 정도로 오버핸드 그립을 잡고 팔꿈치를 옆구리에 고정해요."}, {"title": "밀기", "text": "팔이 완전히 펴질 때까지 바를 밀어 내려요. 아래에서 삼두근을 조여요."}, {"title": "되돌리기", "text": "전완이 바닥과 평행보다 살짝 위에 올 때까지 바를 천천히 올려요. 팔꿈치와 상체는 고정해요."}]},
  "french-press": {"name": "라잉 트라이셉스 익스텐션", "instructions": [{"title": "준비", "text": "플랫 벤치에 누워 EZ바나 스트레이트 바를 좁은 오버핸드 그립으로 잡고, 팔을 펴서 어깨 위로 들어요."}, {"title": "내리기", "text": "팔꿈치만 굽혀 바를 이마 쪽으로 내려요. 위팔은 고정하고 팔꿈치는 위를 향하게 해요."}, {"title": "펴기", "text": "팔을 펴서 바를 다시 어깨 위로 밀어 올려요. 팔꿈치가 바깥으로 벌어지지 않게 해요."}]},
  "pull-up": {"name": "풀업", "instructions": [{"title": "그립 잡기", "text": "어깨너비보다 살짝 넓게 바를 잡고 팔을 편 채 매달려요."}, {"title": "당기기", "text": "턱이 바를 넘거나 바가 가슴 위쪽에 닿을 때까지 팔꿈치를 엉덩이 쪽으로 끌어내려요."}, {"title": "내리기", "text": "아래로 툭 떨어지지 않게 팔이 펴질 때까지 천천히 내려가요."}]},
  "chin-up": {"name": "친업", "instructions": [{"title": "그립 잡기", "text": "손바닥이 몸 쪽을 향하게 어깨너비 정도로 바를 잡고, 팔을 편 채 매달려요."}, {"title": "당기기", "text": "턱이 바를 넘을 때까지 팔꿈치를 몸 앞쪽으로 끌어내려요. 다리는 움직이지 않게 해요."}, {"title": "내리기", "text": "팔이 완전히 펴질 때까지 천천히 내려가요. 반동으로 다음 반복을 시작하지 마세요."}]},
  "lat-pulldown": {"name": "랫 풀다운", "instructions": [{"title": "준비", "text": "허벅지 패드를 조절해 다리를 단단히 고정해요. 어깨보다 살짝 넓게 오버핸드 그립으로 바를 잡아요."}, {"title": "당기기", "text": "상체를 살짝 뒤로 기울이고 팔꿈치를 엉덩이 쪽으로 끌어내리며 바를 가슴 위쪽까지 당겨요."}, {"title": "되돌리기", "text": "팔이 펴지고 광배근이 늘어날 때까지 바를 천천히 올려 보내요. 상체는 고정해요."}]},
  "seated-cable-row": {"name": "클로즈 그립 케이블 로우", "instructions": [{"title": "준비", "text": "낮은 위치의 케이블에 V 핸들을 연결해요. 발판에 발을 올리고 무릎을 살짝 굽힌 채 앉아, 팔을 펴서 핸들을 잡아요."}, {"title": "당기기", "text": "상체를 세우고 팔꿈치를 몸에 붙인 채 핸들을 배 쪽으로 당기며 견갑골을 조여요."}, {"title": "되돌리기", "text": "팔이 펴질 때까지 천천히 되돌려요. 상체는 살짝만 앞으로 기울이고 등을 굽히지 마세요."}]},
  "t-bar-row": {"name": "티바 로우", "instructions": [{"title": "준비", "text": "한쪽 끝이 고정된 바를 다리 사이에 두고 서요. 원판 바로 옆, 바 아래에 V 핸들을 걸고 등을 곧게 편 채 약 45°로 고관절을 접어요."}, {"title": "당기기", "text": "팔꿈치를 뒤로 보내고 견갑골을 조이며 무게를 가슴 쪽으로 당겨 올려요."}, {"title": "내리기", "text": "팔이 펴질 때까지 천천히 내려요. 상체 각도를 유지하고 반동으로 당기지 마세요."}]},
  "deadlift": {"name": "데드리프트", "instructions": [{"title": "준비", "text": "발을 골반 너비로 벌려 바 아래에 두고, 정강이를 바에 가깝게 붙여요. 다리 바로 바깥쪽을 잡아요."}, {"title": "힘주기", "text": "엉덩이는 내리고 가슴은 들고 등은 곧게 펴요. 숨을 깊게 들이마시고 바를 살짝 당겨 느슨함을 없애요."}, {"title": "들어 올리기", "text": "바닥을 밀어내며 똑바로 일어서고, 바는 몸에 가깝게 유지해요. 내릴 때도 같은 방법으로 내려요."}]},
  "hammer-curl": {"name": "해머 컬", "instructions": [{"title": "시작 자세", "text": "덤벨을 몸 옆에 들고 바르게 서요. 손바닥은 몸 쪽을 향하게 하고 팔꿈치는 몸통에 붙여요."}, {"title": "들어 올리기", "text": "엄지가 위를 향한 채 전완이 거의 수직이 될 때까지 덤벨을 들어 올려요. 상체 반동을 쓰지 마세요."}, {"title": "내리기", "text": "뉴트럴 그립을 유지하며 팔이 다시 펴질 때까지 천천히 내려요."}]},
  "dumbbell-curl": {"name": "덤벨 컬", "instructions": [{"title": "시작 자세", "text": "덤벨을 몸 옆에 들고 바르게 서서 팔꿈치를 몸에 붙여요."}, {"title": "들어 올리기", "text": "반동 없이 팔꿈치를 굽혀 덤벨을 어깨 쪽으로 들어 올려요."}, {"title": "내리기", "text": "팔이 다시 펴질 때까지 천천히 내려요."}]},
  "squat": {"name": "백 스쿼트", "instructions": [{"title": "자세 잡기", "text": "발을 어깨너비 정도로 벌리고 발끝은 살짝 바깥을 향하게 해요. 코어에 힘을 줘요."}, {"title": "내려가기", "text": "가슴을 든 채 엉덩이를 다리 사이로 내리듯 앉아요. 무릎은 발끝 방향을 따라가게 해요."}, {"title": "일어서기", "text": "허벅지가 바닥과 평행이 되거나 그보다 낮아지면 발바닥 전체로 밀어 일어서요."}]},
  "hack-squat": {"name": "핵 스쿼트", "instructions": [{"title": "준비", "text": "등과 어깨를 패드에 붙이고 서요. 발은 어깨너비로 벌려 발판 가운데에 둬요."}, {"title": "내려가기", "text": "안전 손잡이를 풀고, 등을 패드에 붙인 채 허벅지가 최소한 바닥과 평행이 될 때까지 무릎을 굽혀요."}, {"title": "일어서기", "text": "무릎을 잠그지 말고 발바닥 전체로 밀어 올려요. 마지막 반복이 끝나면 안전 손잡이를 다시 걸어요."}]},
  "leg-press": {"name": "레그 프레스", "instructions": [{"title": "발 위치", "text": "발을 어깨너비로 벌려 발판 가운데에 두고, 허리를 패드에 붙여요."}, {"title": "내리기", "text": "안전장치를 풀고 무릎을 약 90°까지 굽혀요."}, {"title": "밀기", "text": "무릎을 잠그지 말고 발바닥 전체로 발판을 밀어내요."}]},
  "romanian-deadlift": {"name": "루마니안 데드리프트", "instructions": [{"title": "시작 자세", "text": "바를 골반 앞에 들고 무릎을 살짝 굽힌 채 바르게 서요."}, {"title": "상체 숙이기", "text": "엉덩이를 뒤로 빼면서 햄스트링이 늘어나는 느낌이 들 때까지 바를 허벅지를 따라 내려요."}, {"title": "되돌리기", "text": "엉덩이를 앞으로 밀어 일어서요. 동작 내내 등을 곧게 유지해요."}]},
  "lunge": {"name": "런지", "instructions": [{"title": "서기", "text": "덤벨을 몸 옆에 들고 바르게 서요."}, {"title": "내딛기", "text": "앞으로 크게 한 걸음 내디디며 뒤쪽 무릎을 바닥 쪽으로 내려요."}, {"title": "되돌리기", "text": "앞발로 바닥을 밀어 시작 자세로 돌아온 뒤 다리를 바꿔요."}]},
  "leg-extension": {"name": "레그 익스텐션", "instructions": [{"title": "준비", "text": "무릎을 머신의 회전축에 맞추고 패드를 발목 바로 위에 둬요."}, {"title": "펴기", "text": "다리를 끝까지 펴고 위에서 대퇴사두근을 조여요."}, {"title": "내리기", "text": "무게추가 내려앉지 않게 천천히 내려요."}]},
  "calf-raise": {"name": "스탠딩 카프 레이즈", "instructions": [{"title": "자세 잡기", "text": "발 앞꿈치를 발판 가장자리에 올리고 뒤꿈치는 띄운 채 다리를 펴요."}, {"title": "올라가기", "text": "발끝으로 최대한 높이 올라가 잠깐 멈춰요."}, {"title": "내리기", "text": "충분히 늘어나도록 뒤꿈치를 발판 아래로 천천히 내려요."}]},
  "plank": {"name": "플랭크", "instructions": [{"title": "전완 대기", "text": "팔꿈치를 어깨 아래에 두고 전완을 바닥에 대요."}, {"title": "힘주기", "text": "몸을 들어 일직선으로 만들어요. 엉덩이와 복근에 힘을 줘요."}, {"title": "버티기", "text": "호흡을 일정하게 유지하며 엉덩이가 처지지 않게 자세를 버텨요."}]},
  "paused-bench-press": {"name": "포즈 벤치 프레스", "instructions": [{"title": "준비", "text": "벤치에 누워 눈이 바 바로 아래에 오게 해요. 견갑골을 모으고 발을 바닥에 단단히 디뎌요."}, {"title": "멈추기", "text": "바를 가슴 아래쪽까지 컨트롤하며 내리고, 몸의 긴장을 유지한 채 1~2초간 움직이지 않고 멈춰요."}, {"title": "밀기", "text": "튕기거나 먼저 가라앉지 않고 정지 상태에서 바를 밀어 올려요. 엉덩이는 벤치에 붙여 두세요."}]},
  "larsen-press": {"name": "라센 프레스", "instructions": [{"title": "준비", "text": "벤치에 누워 눈이 바 바로 아래에 오게 해요. 다리를 펴고 발을 바닥에서 살짝 띄워요."}, {"title": "내리기", "text": "바를 랙에서 빼고 가슴 아래쪽까지 컨트롤하며 내려요. 팔꿈치는 몸통에서 약 45° 벌려요."}, {"title": "밀기", "text": "상체 힘만으로 바를 밀어 올려요. 복부에 힘을 줘서 골반이 수평을 유지하고 비틀리지 않게 해요."}]},
  "spoto-press": {"name": "스포토 프레스", "instructions": [{"title": "준비", "text": "평소 벤치 프레스처럼 준비해요. 눈은 바 바로 아래, 견갑골은 모으고, 발은 바닥에 단단히 디뎌요."}, {"title": "멈추기", "text": "바를 컨트롤하며 내리다가 가슴 위 2~3cm 지점에서 멈춰요. 가슴에 닿지 않게 1~2초간 버텨요."}, {"title": "밀기", "text": "멈춘 지점에서 먼저 내려가지 않고 바로 밀어 올려요. 평소 벤치 프레스와 같은 바 경로와 팔꿈치 위치를 유지해요."}]},
  "pin-press": {"name": "핀 프레스", "instructions": [{"title": "준비", "text": "랙의 세이프티 바를 가슴보다 몇 cm 높게 맞추고 그 위에 바를 올려요. 그 아래 벤치에 누워요."}, {"title": "힘주기", "text": "견갑골을 모으고 발을 단단히 디딘 뒤 바를 잡아요. 바가 세이프티 바에서 떨어지기 전에 몸에 긴장을 만들어요."}, {"title": "밀기", "text": "정지 상태에서 팔이 완전히 펴질 때까지 밀어 올린 다음, 바를 세이프티 바 위로 내려 완전히 멈춘 뒤 다음 반복을 해요."}]},
  "floor-press": {"name": "플로어 프레스", "instructions": [{"title": "준비", "text": "랙 안의 바닥에 누워 바가 어깨 위에 오게 하고, 무릎을 굽혀 발바닥을 바닥에 붙여요. 어깨너비보다 살짝 넓게 바를 잡아요."}, {"title": "내리기", "text": "바를 랙에서 빼고 위팔이 바닥에 닿을 때까지 내려요. 팔꿈치는 몸통에서 약 45° 벌리고 잠깐 멈춰요."}, {"title": "밀기", "text": "팔꿈치를 바닥에 튕기지 말고 팔이 완전히 펴질 때까지 바를 다시 밀어 올려요. 견갑골은 뒤로 모아 고정해요."}]},
  "dumbbell-bench-press": {"name": "덤벨 벤치 프레스", "instructions": [{"title": "준비", "text": "덤벨을 허벅지 위에 올리고 플랫 벤치에 앉은 뒤, 뒤로 누우며 덤벨을 가슴 위로 가져와요."}, {"title": "내리기", "text": "덤벨을 가슴 옆으로 내려요. 팔꿈치는 몸통에서 약 45° 벌리고 손목은 팔꿈치 바로 위에 오게 해요."}, {"title": "밀기", "text": "팔이 거의 펴질 때까지 위로, 살짝 안쪽으로 밀어 올려요. 위에서 덤벨끼리 부딪치지 않게 해요."}]},
  "dumbbell-floor-press": {"name": "덤벨 플로어 프레스", "instructions": [{"title": "준비", "text": "덤벨을 허벅지 위에 올리고 바닥에 앉은 뒤, 뒤로 누우며 덤벨을 가슴 위로 밀어 올려요. 무릎을 굽히고 발바닥을 바닥에 붙여요."}, {"title": "내리기", "text": "위팔이 바닥에 닿을 때까지 덤벨을 내려요. 팔꿈치는 몸통에서 약 45° 벌리고 1초간 멈춰요."}, {"title": "밀기", "text": "팔꿈치를 바닥에 튕기지 말고 덤벨을 다시 가슴 위로 밀어 올려요."}]},
  "smith-bench-press": {"name": "스미스 머신 벤치 프레스", "instructions": [{"title": "준비", "text": "바가 가슴 아래쪽과 일직선이 되도록 바 아래에 플랫 벤치를 놓아요. 세이프티 스토퍼는 가슴 높이 바로 아래에 맞춰요."}, {"title": "내리기", "text": "어깨너비보다 살짝 넓게 잡고, 바를 돌려 후크에서 뺀 뒤 가슴 아래쪽까지 컨트롤하며 내려요."}, {"title": "밀기", "text": "팔이 거의 펴질 때까지 바를 곧게 밀어 올려요. 견갑골은 뒤로 모으고 엉덩이는 벤치에 붙여 두세요."}]},
  "smith-close-grip-bench-press": {"name": "스미스 머신 클로즈 그립 벤치 프레스", "instructions": [{"title": "준비", "text": "바가 가슴 아래쪽과 일직선이 되도록 바 아래에 플랫 벤치를 놓아요. 어깨너비 정도로 바를 잡아요."}, {"title": "내리기", "text": "바를 돌려 후크에서 빼고, 팔꿈치를 옆구리에 가깝게 붙인 채 가슴 아래쪽까지 내려요."}, {"title": "밀기", "text": "삼두근으로 밀어낸다는 느낌으로 팔이 펴질 때까지 밀어 올려요. 손목이 팔꿈치 바로 위에 오게 유지해요."}]},
  "chest-press-machine": {"name": "머신 체스트 프레스", "instructions": [{"title": "준비", "text": "손잡이가 가슴 중앙 높이에 오도록 시트를 조절해요. 등을 패드에 붙이고 발은 바닥에 둔 채 앉아요."}, {"title": "밀기", "text": "팔이 거의 펴질 때까지 손잡이를 앞으로 밀어요. 어깨는 뒤로 당겨 패드에 붙여 두세요."}, {"title": "되돌리기", "text": "가슴이 늘어나는 느낌이 들 때까지 손잡이를 천천히 되돌려요. 무게추가 내려앉지 않게 해요."}]},
  "cable-chest-press": {"name": "스탠딩 케이블 체스트 프레스", "instructions": [{"title": "준비", "text": "양쪽 케이블을 가슴 높이에 맞추고 양손에 손잡이를 하나씩 잡아요. 머신을 등지고 한 발 앞으로 내디뎌 다리를 앞뒤로 벌리고 서요."}, {"title": "밀기", "text": "팔이 거의 펴질 때까지 손잡이를 앞으로, 살짝 안쪽으로 모으며 밀어요. 상체는 고정해요."}, {"title": "되돌리기", "text": "가슴이 늘어나는 느낌이 들 때까지 손을 가슴 높이로 천천히 되돌려요. 케이블에 몸이 뒤로 끌려가지 않게 해요."}]},
  "incline-bench-press": {"name": "인클라인 벤치 프레스", "instructions": [{"title": "준비", "text": "벤치를 30~45°로 맞추고 눈이 바 바로 아래에 오게 누워요. 견갑골을 뒤로 모아 내리고 발을 단단히 디뎌요."}, {"title": "내리기", "text": "바를 랙에서 빼고 쇄골 바로 아래, 가슴 위쪽까지 컨트롤하며 내려요. 팔꿈치는 약 45° 벌려요."}, {"title": "밀기", "text": "바가 어깨 위에 오고 팔이 거의 펴질 때까지 위로, 살짝 뒤쪽으로 밀어 올려요."}]},
  "smith-incline-bench-press": {"name": "스미스 머신 인클라인 벤치 프레스", "instructions": [{"title": "준비", "text": "바가 가슴 위쪽과 일직선이 되도록 30~45° 인클라인 벤치를 바 아래에 놓아요. 세이프티 스토퍼는 가슴 높이 바로 아래에 맞춰요."}, {"title": "내리기", "text": "바를 돌려 후크에서 빼고 쇄골 바로 아래, 가슴 위쪽까지 컨트롤하며 내려요."}, {"title": "밀기", "text": "팔이 거의 펴질 때까지 바를 곧게 밀어 올려요. 견갑골은 뒤로 모아 벤치에 붙여 두세요."}]},
  "incline-chest-press-machine": {"name": "머신 인클라인 체스트 프레스", "instructions": [{"title": "준비", "text": "손잡이가 가슴 위쪽 높이에서 시작하도록 시트를 조절해요. 등과 머리를 패드에 붙이고 앉아요."}, {"title": "밀기", "text": "팔이 거의 펴질 때까지 손잡이를 위로, 앞으로 밀어요. 어깨는 내리고 뒤로 당겨 두세요."}, {"title": "되돌리기", "text": "가슴 위쪽이 늘어나는 느낌이 들 때까지 손잡이를 천천히 내리고, 무게추가 내려앉기 전에 다시 밀어요."}]},
  "decline-bench-press": {"name": "디클라인 벤치 프레스", "instructions": [{"title": "준비", "text": "패드 아래에 발을 걸고 눈이 바 바로 아래에 오게 누워요. 바를 랙에서 뺄 때는 보조자의 도움을 받으세요."}, {"title": "내리기", "text": "바를 랙에서 빼고 가슴 아래쪽까지 컨트롤하며 내려요. 팔꿈치는 몸통에서 약 45° 벌려요."}, {"title": "밀기", "text": "팔이 거의 펴질 때까지 바를 곧게 밀어 올려요. 견갑골은 계속 모아 두세요."}]},
  "decline-dumbbell-press": {"name": "디클라인 덤벨 프레스", "instructions": [{"title": "준비", "text": "덤벨을 허벅지 위에 올리고 디클라인 벤치에 앉아요. 패드 아래에 발을 걸고, 덤벨을 가슴에 둔 채 뒤로 누워요."}, {"title": "내리기", "text": "덤벨을 가슴 아래쪽 옆으로 내려요. 팔꿈치는 몸통에서 약 45° 벌려요."}, {"title": "밀기", "text": "팔이 거의 펴질 때까지 위로, 살짝 안쪽으로 모으며 밀어 올려요. 다 끝나면 덤벨을 가슴으로 가져온 뒤 일어나 앉아요."}]},
  "decline-chest-press-machine": {"name": "머신 디클라인 체스트 프레스", "instructions": [{"title": "준비", "text": "손잡이가 가슴 아래쪽 높이에 오도록 시트를 조절해요. 등을 패드에 붙이고 앉아 손잡이를 잡아요."}, {"title": "밀기", "text": "팔이 거의 펴질 때까지 손잡이를 앞쪽 아래로 밀어요. 가슴은 들고 어깨는 뒤로 당겨 두세요."}, {"title": "되돌리기", "text": "무게추가 내려앉지 않게 하면서, 가슴 아래쪽이 늘어나는 느낌이 들 때까지 손잡이를 천천히 되돌려요."}]},
  "pec-deck": {"name": "펙덱 플라이", "instructions": [{"title": "준비", "text": "손잡이가 가슴 높이에 오도록 시트를 조절해요. 등을 패드에 붙이고 앉아 손잡이를 잡아요."}, {"title": "모으기", "text": "팔꿈치를 살짝 굽힌 채 손잡이를 가슴 앞으로 모아요. 1초간 조여요."}, {"title": "벌리기", "text": "가슴이 늘어나는 느낌이 들 때까지 팔을 천천히 벌려요. 어깨는 뒤로 당겨 패드에 붙여 두세요."}]},
  "low-to-high-cable-fly": {"name": "로우 투 하이 케이블 플라이", "instructions": [{"title": "준비", "text": "양쪽 케이블을 가장 낮은 위치에 맞추고 양손에 손잡이를 하나씩 잡은 뒤, 한 발 앞으로 내디뎌 다리를 앞뒤로 벌리고 서요."}, {"title": "올리기", "text": "팔꿈치를 부드럽게 굽힌 채, 손바닥이 위를 향하게 손을 가슴 위쪽 높이까지 쓸어 올리며 모아요."}, {"title": "내리기", "text": "가슴 위쪽이 늘어나는 느낌이 들 때까지 팔을 천천히 아래 바깥쪽으로 내려요."}]},
  "high-to-low-cable-fly": {"name": "하이 투 로우 케이블 플라이", "instructions": [{"title": "준비", "text": "양쪽 케이블을 머리보다 높게 맞추고 양손에 손잡이를 하나씩 잡아요. 한 발 앞으로 내디뎌 다리를 앞뒤로 벌리고, 상체를 살짝 앞으로 기울여요."}, {"title": "끌어내리기", "text": "팔꿈치를 부드럽게 굽힌 채 손을 아래로 쓸어내리며 모아, 아랫배 앞에서 만나게 해요."}, {"title": "되돌리기", "text": "가슴 아래쪽이 늘어나는 느낌이 들 때까지 팔을 천천히 위 바깥쪽으로 되돌려요."}]},
  "dumbbell-fly": {"name": "덤벨 플라이", "instructions": [{"title": "준비", "text": "플랫 벤치에 누워 덤벨을 가슴 위로 밀어 올려요. 손바닥은 서로 마주 보게 하고 팔꿈치는 살짝 굽혀요."}, {"title": "벌리기", "text": "가슴이 늘어나는 느낌이 들 때까지 덤벨을 크게 호를 그리며 옆으로 내려요. 팔꿈치 각도는 고정해요."}, {"title": "모으기", "text": "나무를 껴안듯 같은 호를 따라 덤벨을 다시 들어 올리고, 서로 닿기 직전에 멈춰요."}]},
  "incline-dumbbell-fly": {"name": "인클라인 덤벨 플라이", "instructions": [{"title": "준비", "text": "벤치를 30~45°로 맞추고 누운 뒤, 덤벨을 가슴 위쪽 위로 밀어 올려요. 손바닥은 서로 마주 보게 해요."}, {"title": "벌리기", "text": "팔꿈치를 살짝 굽힌 채 가슴 위쪽이 늘어나는 느낌이 들 때까지 덤벨을 크게 호를 그리며 옆으로 내려요."}, {"title": "모으기", "text": "같은 호를 따라 덤벨을 다시 가슴 위쪽 위로 모아요. 어깨는 내리고 뒤로 당겨 두세요."}]},
  "dumbbell-pullover": {"name": "덤벨 풀오버", "instructions": [{"title": "준비", "text": "플랫 벤치에 누워 덤벨 하나를 가슴 위로 들어요. 양손으로 위쪽 원판을 감싸 쥐고 팔꿈치는 살짝 굽혀요."}, {"title": "내리기", "text": "가슴과 광배근이 늘어나는 느낌이 들 때까지 덤벨을 호를 그리며 머리 뒤로 내려요."}, {"title": "당기기", "text": "같은 호를 따라 덤벨을 다시 가슴 위로 당겨요. 갈비뼈를 내려 허리가 젖혀지지 않게 해요."}]},
  "knee-push-up": {"name": "무릎 푸시업", "instructions": [{"title": "플랭크 자세", "text": "무릎을 꿇고 손을 어깨보다 살짝 넓게 바닥에 짚어요. 머리부터 무릎까지 일직선을 만들어요."}, {"title": "내리기", "text": "팔꿈치를 몸통에서 약 45° 벌린 채 가슴을 바닥 쪽으로 내려요. 엉덩이는 뒤로 빼지 말고 일직선을 유지해요."}, {"title": "밀기", "text": "팔이 펴질 때까지 바닥을 밀어내요. 복부에 힘을 줘서 허리가 처지지 않게 해요."}]},
  "incline-push-up": {"name": "인클라인 푸시업", "instructions": [{"title": "플랭크 자세", "text": "벤치, 박스나 바에 어깨보다 살짝 넓게 손을 짚어요. 몸이 일직선이 될 때까지 발을 뒤로 옮겨요."}, {"title": "내리기", "text": "팔꿈치를 몸통에서 약 45° 벌린 채 가슴을 모서리 쪽으로 내려요. 머리부터 발뒤꿈치까지 일직선을 유지해요."}, {"title": "밀기", "text": "팔이 펴질 때까지 밀어내요. 점차 더 낮은 곳을 짚어 난도를 높여요."}]},
  "decline-push-up": {"name": "디클라인 푸시업", "instructions": [{"title": "플랭크 자세", "text": "발은 벤치나 박스 위에 올리고, 손은 어깨보다 살짝 넓게 바닥에 짚어요. 머리부터 발뒤꿈치까지 몸을 곧게 펴요."}, {"title": "내리기", "text": "팔꿈치를 몸통에서 약 45° 벌린 채 가슴을 바닥 쪽으로 내려요. 목은 중립을 유지하고 엉덩이가 위로 솟지 않게 해요."}, {"title": "밀기", "text": "팔이 펴질 때까지 바닥을 밀어내요. 복부와 엉덩이에 힘을 줘서 골반이 처지지 않게 해요."}]},
  "deficit-push-up": {"name": "디피싯 푸시업", "instructions": [{"title": "플랭크 자세", "text": "원판 두 개, 블록이나 푸시업 바 위에 어깨보다 살짝 넓게 손을 짚어요. 머리부터 발뒤꿈치까지 몸을 곧게 펴요."}, {"title": "내리기", "text": "가슴이 깊게 늘어나는 느낌이 들 때까지 손 높이보다 아래로 가슴을 내려요. 팔꿈치는 약 45° 벌려요."}, {"title": "밀기", "text": "팔이 펴질 때까지 다시 밀어 올려요. 어깨가 편안한 범위까지만 내려가요."}]},
  "overhead-press": {"name": "오버헤드 프레스", "instructions": [{"title": "준비", "text": "바를 쇄골 높이에서 랙에서 빼요. 손은 어깨 바로 바깥쪽을 잡고 전완은 수직으로 세워요. 엉덩이와 복근에 힘을 줘요."}, {"title": "밀기", "text": "곧게 밀어 올리면서 턱에 걸리지 않게 머리를 뒤로 빼고, 바가 이마를 지나면 머리를 다시 앞으로 넣어요."}, {"title": "내리기", "text": "바가 발 중앙 위에 오도록 팔을 완전히 편 뒤, 상체를 뒤로 젖히지 않고 쇄골까지 컨트롤하며 내려요."}]},
  "seated-barbell-press": {"name": "시티드 바벨 숄더 프레스", "instructions": [{"title": "준비", "text": "랙 안에 등받이를 세운 벤치를 놓고, 앉았을 때 바가 어깨 바로 아래 높이에 오게 맞춰요. 등을 패드에 붙이고 앉아요."}, {"title": "밀기", "text": "손을 어깨 바로 바깥쪽에 두고 바를 랙에서 뺀 뒤 곧게 밀어 올려요. 바가 지나가도록 머리를 살짝 뒤로 빼요."}, {"title": "내리기", "text": "바를 가슴 위쪽까지 컨트롤하며 내려요. 등이 젖혀져 패드에서 떨어지지 않게 붙여 두세요."}]},
  "behind-the-neck-press": {"name": "비하인드 넥 프레스", "instructions": [{"title": "준비", "text": "앉거나 선 자세로 스쿼트할 때처럼 바를 등 위쪽에 올려요. 손은 오버헤드 프레스보다 살짝 넓게 잡아요."}, {"title": "밀기", "text": "팔이 완전히 펴질 때까지 머리 뒤에서 바를 곧게 밀어 올려요. 머리는 중립을 유지하고 턱을 살짝 당겨요."}, {"title": "내리기", "text": "바를 귀 높이 정도까지 천천히 내려요. 가벼운 무게를 쓰고, 어깨가 끼이는 느낌이 들면 이 운동은 건너뛰세요."}]},
  "z-press": {"name": "Z 프레스", "instructions": [{"title": "준비", "text": "랙 안의 바닥에 앉아 다리를 앞으로 곧게 뻗어요. 쇄골 높이에서 바를 뺄 수 있도록 후크 높이를 맞춰요."}, {"title": "힘주기", "text": "상체를 뒤로 기울이지 말고 곧게 앉아 복부에 강하게 힘을 줘요. 등을 받쳐 주는 게 없으니 몸통을 단단히 고정해야 해요."}, {"title": "밀기", "text": "팔이 완전히 펴질 때까지 바를 곧게 밀어 올리고, 바가 지나가도록 머리를 살짝 뒤로 빼요. 그다음 컨트롤하며 내려요."}]},
  "push-press": {"name": "푸시 프레스", "instructions": [{"title": "준비", "text": "바를 쇄골 위에 올리고 손은 어깨 바로 바깥쪽을 잡아요. 발은 골반 너비로 벌리고 코어에 힘을 줘요."}, {"title": "굽혔다 밀기", "text": "상체를 세운 채 무릎을 굽혀 몇 cm 내려간 뒤, 다리로 폭발적으로 밀어 올려요."}, {"title": "밀기", "text": "그 반동을 이용해 팔이 완전히 펴질 때까지 바를 머리 위로 밀어 올려요. 바를 쇄골로 내릴 때는 무릎을 굽혀 충격을 흡수해요."}]},
  "single-arm-dumbbell-press": {"name": "원암 덤벨 숄더 프레스", "instructions": [{"title": "준비", "text": "서거나 앉은 자세로 몸을 곧게 세우고, 덤벨 하나를 어깨 높이로 들어 손목이 팔꿈치 바로 위에 오게 해요. 복부와 엉덩이에 힘을 줘요."}, {"title": "밀기", "text": "팔이 완전히 펴질 때까지 덤벨을 곧게 밀어 올려요. 몸이 반대쪽으로 기울지 않게 해요."}, {"title": "내리기", "text": "덤벨을 어깨 높이까지 컨트롤하며 내려요. 한쪽 반복을 모두 마친 뒤 반대쪽으로 바꿔요."}]},
  "smith-shoulder-press": {"name": "스미스 머신 숄더 프레스", "instructions": [{"title": "준비", "text": "바가 얼굴 바로 앞을 지나가도록 스미스 머신 아래에 등받이를 세운 벤치를 놓아요. 등을 패드에 붙이고 앉아요."}, {"title": "밀기", "text": "손을 어깨 바로 바깥쪽에 두고 바를 돌려 후크에서 뺀 뒤, 팔이 거의 펴질 때까지 밀어 올려요."}, {"title": "내리기", "text": "바를 턱 높이나 그보다 살짝 아래까지 컨트롤하며 내려요. 등은 패드에 붙이고 복부에 힘을 유지해요."}]},
  "landmine-press": {"name": "랜드마인 프레스", "instructions": [{"title": "준비", "text": "바벨 한쪽 끝을 랜드마인이나 구석에 끼워요. 다른 쪽 끝을 한 손으로 어깨 높이에 들고, 발은 앞뒤로 엇갈리게 서요."}, {"title": "밀기", "text": "팔이 펴질 때까지 바를 위로, 앞으로 밀어요. 끝 지점에서는 견갑골이 앞으로 미끄러지듯 따라 나오게 해요."}, {"title": "내리기", "text": "바를 어깨까지 컨트롤하며 내려요. 골반은 정면을 향하게 유지하고 상체를 뒤로 젖히지 마세요."}]},
  "pike-push-up": {"name": "파이크 푸시업", "instructions": [{"title": "준비", "text": "푸시업 자세에서 시작해 발을 손 쪽으로 옮기며 엉덩이를 들어, 몸이 거꾸로 된 V자가 되게 해요."}, {"title": "내리기", "text": "팔꿈치를 굽혀 정수리를 손 바로 앞 바닥 쪽으로 내려요. 팔꿈치는 옆이 아니라 뒤를 향하게 해요."}, {"title": "밀기", "text": "엉덩이를 높게 유지한 채 팔이 펴질 때까지 다시 밀어 올려요. 더 어렵게 하려면 발을 박스 위에 올려요."}]},
  "cable-lateral-raise": {"name": "케이블 레터럴 레이즈", "instructions": [{"title": "준비", "text": "케이블을 가장 낮은 위치에 맞추고 머신을 옆에 두고 서요. 머신에서 먼 쪽 손으로 손잡이를 잡아 허벅지 앞에 둬요."}, {"title": "올리기", "text": "팔꿈치를 살짝 굽힌 채, 팔꿈치가 먼저 올라가게 하며 팔을 옆으로 어깨 높이까지 들어 올려요."}, {"title": "내리기", "text": "2~3초에 걸쳐 천천히 내리고, 손이 몸 앞쪽으로 오게 해서 긴장을 유지해요."}]},
  "machine-lateral-raise": {"name": "머신 레터럴 레이즈", "instructions": [{"title": "준비", "text": "어깨가 머신의 회전축과 맞도록 시트를 조절해요. 팔을 패드에 대요."}, {"title": "올리기", "text": "팔꿈치가 먼저 올라가게 하며 팔을 옆으로 어깨 높이까지 들어 올려요. 어깨를 으쓱하지 마세요."}, {"title": "내리기", "text": "2~3초에 걸쳐 패드를 천천히 내리고, 무게추가 내려앉기 전에 멈춰요."}]},
  "y-raise": {"name": "Y 레이즈", "instructions": [{"title": "준비", "text": "30~45°로 맞춘 인클라인 벤치에 엎드려 양손에 가벼운 덤벨을 하나씩 들어요. 팔은 늘어뜨리고 엄지는 위를 향하게 해요."}, {"title": "올리기", "text": "팔이 몸과 일직선이 될 때까지 앞쪽 바깥으로 Y자를 그리며 들어 올려요. 어깨는 내려서 귀에서 멀어지게 해요."}, {"title": "내리기", "text": "덤벨을 천천히 다시 내려요. 팔을 길게 뻗는 동작이라 보기보다 어려우니 가벼운 무게를 써요."}]},
  "cable-front-raise": {"name": "케이블 프론트 레이즈", "instructions": [{"title": "준비", "text": "낮은 위치의 케이블을 등지고 서서 케이블이 다리 사이로 지나가게 해요. 손잡이나 로프를 허벅지 앞에서 잡아요."}, {"title": "올리기", "text": "팔꿈치를 살짝 굽힌 채 팔을 몸 앞으로 곧게 어깨 높이까지 들어 올려요. 상체를 뒤로 젖히지 마세요."}, {"title": "내리기", "text": "2~3초에 걸쳐 천천히 내리고, 무게추가 내려앉기 직전에 멈춰요."}]},
  "cable-rear-delt-fly": {"name": "케이블 리어 델트 플라이", "instructions": [{"title": "준비", "text": "양쪽 케이블을 어깨 높이에 맞춰요. 왼쪽 케이블은 오른손, 오른쪽 케이블은 왼손으로 잡고 뒤로 물러서요."}, {"title": "당겨 벌리기", "text": "팔꿈치를 살짝 굽힌 채 팔이 어깨와 일직선이 될 때까지 크게 호를 그리며 바깥 뒤쪽으로 당겨요."}, {"title": "되돌리기", "text": "손이 몸 앞에서 교차할 때까지 천천히 되돌려요. 어깨를 으쓱하거나 상체를 뒤로 젖히지 마세요."}]},
  "reverse-pec-deck": {"name": "리버스 펙덱 플라이", "instructions": [{"title": "준비", "text": "가슴 패드를 마주 보고 앉아 손잡이가 어깨 높이에 오도록 시트를 조절해요. 팔을 앞으로 곧게 뻗어 손잡이를 잡아요."}, {"title": "당겨 벌리기", "text": "팔꿈치를 살짝 굽힌 채 팔이 몸통과 일직선이 될 때까지 바깥 뒤쪽으로 벌려요. 가슴은 패드에 붙여 두세요."}, {"title": "되돌리기", "text": "무게추가 내려앉지 않게 하면서, 손이 다시 몸 앞에 올 때까지 손잡이를 천천히 앞으로 가져와요."}]},
  "cable-upright-row": {"name": "케이블 업라이트 로우", "instructions": [{"title": "그립 잡기", "text": "낮은 위치의 케이블에 스트레이트 바나 로프를 연결해요. 가까이 서서 어깨너비 정도로 잡고 허벅지 앞에 들어요."}, {"title": "당기기", "text": "팔꿈치가 먼저 올라가게 하며 가슴 아래쪽 높이까지 당겨 올려요. 팔꿈치는 항상 손보다 높게 유지해요."}, {"title": "내리기", "text": "컨트롤하며 내리고, 아래에서도 케이블이 팽팽하게 유지되게 해요. 어깨가 끼이는 느낌이 들면 더 일찍 멈춰요."}]},
  "cable-external-rotation": {"name": "케이블 외회전", "instructions": [{"title": "준비", "text": "케이블을 팔꿈치 높이에 맞추고 머신을 옆에 두고 서요. 머신에서 먼 쪽 손으로 손잡이를 잡고, 팔꿈치를 90°로 굽혀 옆구리에 붙여요."}, {"title": "돌리기", "text": "전완을 배에서 멀어지도록 편안한 범위까지 바깥쪽으로 돌려요. 팔꿈치는 옆구리에 고정해요."}, {"title": "되돌리기", "text": "전완을 배 앞쪽으로 천천히 되돌려요. 가벼운 무게로 반동 없이 부드럽게 움직여요."}]},
  "neutral-grip-pull-up": {"name": "뉴트럴 그립 풀업", "instructions": [{"title": "그립 잡기", "text": "손바닥이 서로 마주 보게 평행 손잡이를 잡고 팔을 편 채 매달려요."}, {"title": "당기기", "text": "턱이 손잡이를 넘을 때까지 팔꿈치를 몸에 가깝게 붙여 끌어내려요."}, {"title": "내리기", "text": "팔이 펴질 때까지 천천히 내려가요. 다리는 고정하고 몸이 흔들리지 않게 해요."}]},
  "negative-pull-up": {"name": "네거티브 풀업", "instructions": [{"title": "준비", "text": "박스를 밟고 올라서거나 점프해서 턱이 바보다 위에 오게 해요. 손바닥은 앞을 향하게, 손은 어깨너비로 잡아요."}, {"title": "내리기", "text": "팔이 완전히 펴질 때까지 최대한 천천히, 3–5초를 목표로 몸을 내려요."}, {"title": "다시 준비", "text": "다시 박스에 올라서서 위에서 다음 반복을 시작해요. 아래에서 툭 떨어지지 말고 긴장을 유지해요."}]},
  "assisted-pull-up-machine": {"name": "어시스티드 풀업 머신", "instructions": [{"title": "준비", "text": "보조 무게를 선택해요. 무게가 무거울수록 더 많이 도와줘요. 패드에 무릎을 대거나 발판에 서서 손잡이를 잡아요."}, {"title": "당기기", "text": "턱이 손잡이 위로 올라올 때까지 팔꿈치를 골반 쪽으로 끌어내려요."}, {"title": "내리기", "text": "팔이 펴질 때까지 천천히 내려요. 근력이 늘면 보조 무게를 점점 줄여요."}]},
  "close-grip-lat-pulldown": {"name": "클로즈 그립 랫 풀다운", "instructions": [{"title": "준비", "text": "V 핸들을 걸고 허벅지를 패드 아래에 넣고 앉아요. 팔을 쭉 편 채 핸들을 잡아요."}, {"title": "당기기", "text": "상체를 살짝 뒤로 젖히고 팔꿈치를 아래 뒤로 보내며 핸들을 가슴 위쪽까지 당겨요."}, {"title": "되돌리기", "text": "팔이 펴지고 광배근이 늘어날 때까지 핸들을 천천히 올려 보내요."}]},
  "underhand-lat-pulldown": {"name": "언더핸드 랫 풀다운", "instructions": [{"title": "그립 잡기", "text": "손바닥이 몸 쪽을 향하게 어깨너비 정도로 바를 잡고, 허벅지를 패드 아래에 넣고 앉아요."}, {"title": "당기기", "text": "팔꿈치를 몸 가까이, 몸 앞쪽에 둔 채 바를 가슴 위쪽까지 당겨요."}, {"title": "되돌리기", "text": "팔이 완전히 펴질 때까지 바를 천천히 올려 보내요. 상체를 뒤로 흔들어 무게를 옮기지 마세요."}]},
  "single-arm-lat-pulldown": {"name": "원암 랫 풀다운", "instructions": [{"title": "준비", "text": "상단 풀리에 싱글 핸들을 걸어요. 앉거나 무릎을 꿇고, 한 팔을 머리 위로 쭉 뻗어 핸들을 잡아요."}, {"title": "당기기", "text": "손이 어깨 옆에 올 때까지 팔꿈치를 옆구리 쪽으로 끌어내려요. 상체를 비틀지 마세요."}, {"title": "되돌리기", "text": "팔을 천천히 올리며 옆구리가 늘어나는 걸 느껴요. 모든 반복을 마치면 팔을 바꿔요."}]},
  "machine-lat-pulldown": {"name": "머신 랫 풀다운", "instructions": [{"title": "준비", "text": "허벅지 패드가 몸을 단단히 눌러 주도록 시트를 조절해요. 팔을 편 채 손잡이를 잡아요."}, {"title": "당기기", "text": "팔꿈치를 골반 쪽으로 보내며 손잡이를 어깨 높이까지 당겨요. 가슴은 편 상태를 유지해요."}, {"title": "되돌리기", "text": "팔이 펴질 때까지 손잡이를 천천히 올려 보내요. 반복 사이에 무게를 내려놓지 마세요."}]},
  "straight-arm-pulldown": {"name": "스트레이트 암 풀다운", "instructions": [{"title": "준비", "text": "상단 풀리에 스트레이트 바나 로프를 걸어요. 뒤로 물러나 상체를 살짝 숙이고, 팔을 편 채 눈높이에서 잡아요."}, {"title": "당기기", "text": "팔꿈치를 거의 편 채 고정하고 바를 호를 그리듯 허벅지까지 쓸어내려요. 광배근을 조여요."}, {"title": "되돌리기", "text": "팔꿈치를 굽히거나 어깨를 으쓱하지 말고 바를 눈높이까지 천천히 올려 보내요."}]},
  "barbell-row": {"name": "바벨 로우", "instructions": [{"title": "준비", "text": "무릎 바로 바깥쪽 너비로 바를 오버핸드 그립으로 잡아요. 등을 곧게 펴고 무릎을 살짝 굽힌 채 상체를 약 45°까지 숙여요."}, {"title": "당기기", "text": "팔꿈치를 뒤로 보내고 견갑골을 모으며 바를 아랫갈비뼈 쪽으로 당겨요."}, {"title": "내리기", "text": "팔이 펴질 때까지 바를 통제하며 내려요. 상체 각도를 유지하고 엉덩이 반동을 쓰지 마세요."}]},
  "underhand-barbell-row": {"name": "언더핸드 바벨 로우", "instructions": [{"title": "준비", "text": "어깨너비로 언더핸드 그립을 잡고, 등을 곧게 펴고 무릎을 살짝 굽힌 채 상체를 약 45°까지 숙여요."}, {"title": "당기기", "text": "팔꿈치를 옆구리에 가깝게 붙인 채 바를 배꼽 쪽으로 당겨요."}, {"title": "내리기", "text": "팔이 펴질 때까지 바를 천천히 내려요. 손목은 곧게 유지하고 컬 동작이 되지 않게 해요."}]},
  "pendlay-row": {"name": "펜들레이 로우", "instructions": [{"title": "준비", "text": "바는 바닥에, 발 중앙 위에 둬요. 상체가 바닥과 거의 평행해질 때까지 숙이고, 등을 곧게 편 채 오버핸드 그립으로 잡아요."}, {"title": "당기기", "text": "상체를 들지 않고 바닥에서 가슴 아래쪽까지 바를 폭발적으로 당겨요."}, {"title": "다시 준비", "text": "바를 바닥에 내려 완전히 멈추게 해요. 매 반복 전에 복압을 다시 잡아요."}]},
  "seal-row": {"name": "실 로우", "instructions": [{"title": "준비", "text": "팔을 뻗었을 때 바가 몸 아래에 매달릴 만큼 높인 벤치에 엎드려요. 어깨너비로 오버핸드 그립을 잡아요."}, {"title": "당기기", "text": "팔꿈치를 뒤로 보내며 바를 벤치 아랫면까지 당겨요. 가슴과 골반은 패드에 붙여요."}, {"title": "내리기", "text": "팔이 펴질 때까지 바를 천천히 내리고 견갑골이 벌어지게 해요. 다리를 차거나 몸을 흔들지 마세요."}]},
  "meadows-row": {"name": "메도우스 로우", "instructions": [{"title": "준비", "text": "랜드마인 바 옆으로 서서 다리를 앞뒤로 엇갈리게 두고, 바 끝(슬리브)을 오버핸드 그립으로 잡아요. 반대쪽 팔뚝은 앞쪽 무릎에 올려요."}, {"title": "당기기", "text": "팔꿈치를 위로, 살짝 바깥으로 보내며 바를 골반 쪽으로 당겨요."}, {"title": "내리기", "text": "팔이 펴지고 광배근이 늘어나는 느낌이 들 때까지 바를 내려요. 한 세트를 마치면 방향을 바꿔요."}]},
  "one-arm-dumbbell-row": {"name": "원암 덤벨 로우", "instructions": [{"title": "준비", "text": "평평한 벤치에 한쪽 무릎과 같은 쪽 손을 올려요. 등을 곧게 편 채 반대쪽 손으로 덤벨을 잡아요."}, {"title": "당기기", "text": "팔꿈치를 몸 가까이 붙인 채 덤벨을 골반 쪽으로 당겨요. 상체를 돌리지 마세요."}, {"title": "내리기", "text": "팔이 펴지고 광배근이 늘어나는 느낌이 들 때까지 덤벨을 내려요. 한 세트를 마치면 방향을 바꿔요."}]},
  "bent-over-dumbbell-row": {"name": "벤트오버 덤벨 로우", "instructions": [{"title": "준비", "text": "양손에 덤벨을 하나씩 들고 손바닥이 서로 마주 보게 해요. 무릎을 살짝 굽히고 등을 곧게 편 채 상체를 약 45°까지 숙여요."}, {"title": "당기기", "text": "팔꿈치를 뒤로 보내고 견갑골을 모으며 두 덤벨을 골반 쪽으로 당겨요."}, {"title": "내리기", "text": "팔이 펴질 때까지 덤벨을 천천히 내려요. 세트 내내 상체를 고정해요."}]},
  "chest-supported-dumbbell-row": {"name": "체스트 서포티드 덤벨 로우", "instructions": [{"title": "준비", "text": "인클라인 벤치를 30–45°로 맞추고 가슴을 패드에 대고 엎드려요. 양손에 덤벨을 하나씩 들어요."}, {"title": "당기기", "text": "덤벨을 갈비뼈 옆까지 당기고 견갑골을 모아요. 가슴은 패드에 붙여요."}, {"title": "내리기", "text": "팔이 펴지고 어깨가 앞으로 뻗어질 때까지 천천히 내려요."}]},
  "wide-grip-cable-row": {"name": "와이드 그립 케이블 로우", "instructions": [{"title": "준비", "text": "하단 풀리에 긴 바를 걸어요. 발판에 발을 올리고 무릎을 살짝 굽힌 채 앉아, 바를 넓게 오버핸드 그립으로 잡아요."}, {"title": "당기기", "text": "팔꿈치를 양옆으로 벌린 채 바를 가슴 아래쪽까지 당겨요. 등 상부를 조여요."}, {"title": "되돌리기", "text": "상체를 곧게 세워 고정한 채 팔이 펴질 때까지 천천히 뻗어요."}]},
  "single-arm-cable-row": {"name": "원암 케이블 로우", "instructions": [{"title": "준비", "text": "하단이나 가슴 높이 풀리에 싱글 핸들을 걸어요. 머신을 마주 보고 앉거나 서서 한 팔을 편 채 핸들을 잡아요."}, {"title": "당기기", "text": "팔꿈치를 몸통 뒤까지 보내며 핸들을 옆구리로 당겨요. 어깨가 정면을 향하게 유지해요."}, {"title": "되돌리기", "text": "팔을 천천히 앞으로 뻗어 충분히 늘려요. 한 세트를 마치면 팔을 바꿔요."}]},
  "machine-row": {"name": "시티드 머신 로우", "instructions": [{"title": "준비", "text": "손잡이가 가슴 높이에 오도록 시트를 조절하고 가슴을 패드에 붙여요."}, {"title": "당기기", "text": "팔꿈치를 뒤로 보내고 견갑골을 모으며 손잡이를 몸통 쪽으로 당겨요."}, {"title": "되돌리기", "text": "팔이 펴질 때까지 손잡이를 천천히 앞으로 보내요. 가슴은 패드에 붙여요."}]},
  "machine-high-row": {"name": "머신 하이 로우", "instructions": [{"title": "준비", "text": "팔을 위로 쭉 뻗어야 손잡이에 닿도록 시트를 조절해요. 허벅지를 패드 아래에 고정해요."}, {"title": "당기기", "text": "팔꿈치가 몸통을 지날 때까지 손잡이를 가슴 아래쪽을 향해 아래 뒤로 당겨요."}, {"title": "되돌리기", "text": "팔이 펴지고 광배근이 늘어날 때까지 손잡이를 천천히 올려 보내요."}]},
  "chest-supported-t-bar-row": {"name": "체스트 서포티드 티바 로우", "instructions": [{"title": "준비", "text": "발판 위에 서서 가슴을 패드에 대고 엎드려요. 팔을 편 채 손잡이를 잡아요."}, {"title": "당기기", "text": "팔꿈치를 뒤로 보내며 손잡이를 가슴 쪽으로 당겨요. 가슴은 패드에 붙여요."}, {"title": "내리기", "text": "팔이 펴지고 견갑골이 벌어질 때까지 천천히 내려요."}]},
  "inverted-row": {"name": "인버티드 로우", "instructions": [{"title": "준비", "text": "랙이나 스미스 머신에 바를 허리 높이 정도로 설치해요. 바 아래에 누워 오버핸드 그립으로 잡고 몸을 일직선으로 펴요."}, {"title": "당기기", "text": "머리부터 발뒤꿈치까지 몸을 일직선으로 유지하며 가슴을 바 쪽으로 당겨요. 견갑골을 모아요."}, {"title": "내리기", "text": "골반이 처지지 않게 팔이 펴질 때까지 몸을 내려요. 무릎을 굽히면 더 쉬워져요."}]},
  "sumo-deadlift": {"name": "스모 데드리프트", "instructions": [{"title": "준비", "text": "발을 넓게 벌리고 발끝을 바깥으로 돌린 채 정강이를 바에 가깝게 붙여요. 무릎 안쪽에서 바를 잡고 팔은 아래로 곧게 늘어뜨려요."}, {"title": "복압 잡기", "text": "무릎을 발끝 방향으로 밀어 벌리고, 가슴을 펴고 등을 곧게 해요. 숨을 깊게 들이마시고 바를 살짝 당겨 유격을 없애요."}, {"title": "들어 올리기", "text": "발로 바닥을 양옆으로 밀어내듯 하며 골반을 앞으로 밀어 일어서요. 내릴 때도 같은 방법으로 바를 다리에 가깝게 내려요."}]},
  "trap-bar-deadlift": {"name": "트랩바 데드리프트", "instructions": [{"title": "준비", "text": "트랩바 가운데에 서서 발을 골반 너비로 벌려요. 손잡이 가운데를 잡고 팔은 몸 옆에 곧게 둬요."}, {"title": "복압 잡기", "text": "고관절과 무릎을 굽히고, 가슴을 펴고 등을 곧게 해요. 숨을 깊게 들이마시고 코어에 힘을 줘요."}, {"title": "들어 올리기", "text": "발바닥 전체로 밀며 고관절과 무릎을 함께 펴서 똑바로 일어서요. 바는 통제하며 내려요."}]},
  "rack-pull": {"name": "랙 풀", "instructions": [{"title": "준비", "text": "안전바나 블록 위에 바를 무릎 바로 아래나 위 높이로 올려요. 발은 골반 너비로 벌리고, 다리 바로 바깥쪽을 잡아요."}, {"title": "복압 잡기", "text": "등을 곧게 편 채 상체를 숙이고 어깨가 바보다 살짝 앞에 오게 해요. 숨을 들이마시고 바를 살짝 당겨 유격을 없애요."}, {"title": "들어 올리기", "text": "골반을 앞으로 밀어 똑바로 일어서고, 맨 위에서 둔근을 조여요. 바를 통제하며 안전바 위로 다시 내려요."}]},
  "deficit-deadlift": {"name": "디피싯 데드리프트", "instructions": [{"title": "준비", "text": "2–5cm 높이의 원판이나 플랫폼 위에 서서 바가 발 중앙 위에 오게 해요. 다리 바로 바깥쪽을 잡아요."}, {"title": "복압 잡기", "text": "일반 데드리프트보다 골반을 낮추고, 가슴을 펴고 등을 곧게 해요. 숨을 들이마시고 바를 살짝 당겨 유격을 없애요."}, {"title": "들어 올리기", "text": "바닥을 밀어내며, 바가 바닥에서 떨어질 때 몸에 가깝게 유지해요. 똑바로 일어선 뒤 같은 방법으로 내려요."}]},
  "paused-deadlift": {"name": "포즈 데드리프트", "instructions": [{"title": "준비", "text": "일반 데드리프트처럼 준비해요. 발은 골반 너비, 바는 발 중앙 위, 그립은 다리 바로 바깥쪽, 등은 곧게 펴요."}, {"title": "멈추기", "text": "바를 바닥에서 살짝 들거나 무릎 바로 아래까지 올린 뒤 1–2초 멈춰요. 등을 곧게 펴고 바를 몸에 가깝게 유지해요."}, {"title": "마무리", "text": "계속 올라가 똑바로 일어선 뒤, 바를 통제하며 바닥까지 내려요."}]},
  "back-extension": {"name": "백 익스텐션", "instructions": [{"title": "준비", "text": "45° 또는 수평 벤치에서 패드가 골반뼈 바로 아래에 오게 맞추고, 발뒤꿈치를 발 패드 아래에 걸어요."}, {"title": "내리기", "text": "고관절을 접어 햄스트링이 늘어나는 느낌이 들 때까지 등을 곧게 편 채 상체를 내려요."}, {"title": "올라오기", "text": "둔근을 조이며 몸이 일직선이 될 때까지 올라와요. 허리를 과하게 젖히지 마세요. 부하를 더하려면 원판을 가슴에 안아요."}]},
  "back-extension-machine": {"name": "백 익스텐션 머신", "instructions": [{"title": "준비", "text": "등 패드가 견갑골에 걸치도록 시트를 조절해요. 허벅지 스트랩을 채우고 발을 단단히 디뎌요."}, {"title": "펴기", "text": "상체가 수직보다 살짝 뒤로 갈 때까지 패드를 뒤로 밀어요. 반동 없이 부드럽게 움직여요."}, {"title": "되돌리기", "text": "패드를 따라 상체를 천천히 앞으로 가져와요. 복근에 힘을 주고 앞으로 왔을 때도 긴장을 놓지 마세요."}]},
  "superman": {"name": "슈퍼맨", "instructions": [{"title": "준비", "text": "엎드려서 팔을 앞으로 쭉 뻗고 다리도 곧게 펴요."}, {"title": "들어 올리기", "text": "둔근과 허리에 힘을 줘서 팔, 가슴, 허벅지를 바닥에서 들어 올려요. 1–2초 버텨요."}, {"title": "내리기", "text": "천천히 내려와 잠깐 힘을 빼요. 시선은 바닥을 향해 목을 중립으로 유지해요."}]},
  "reverse-hyperextension": {"name": "리버스 하이퍼 익스텐션", "instructions": [{"title": "준비", "text": "골반이 패드 끝에 오도록 엎드려 손잡이를 잡아요. 발목을 스트랩이나 롤러에 걸어요."}, {"title": "들어 올리기", "text": "둔근을 조여 다리가 상체와 일직선이 될 때까지 들어 올려요. 맨 위에서 허리를 과하게 젖히지 마세요."}, {"title": "내리기", "text": "다리가 아래로 곧게 늘어질 때까지 통제하며 내려요. 반동에 맡기지 말고 흔들림을 제어해요."}]},
  "dumbbell-shrug": {"name": "덤벨 슈러그", "instructions": [{"title": "준비", "text": "양손에 덤벨을 들어 몸 옆에 두고 똑바로 서요. 손바닥은 안쪽을 향하고 팔은 곧게 펴요."}, {"title": "어깨 올리기", "text": "어깨를 귀 쪽으로 최대한 높이 곧게 들어 올려요. 어깨를 돌리거나 팔꿈치를 굽히지 마세요."}, {"title": "내리기", "text": "맨 위에서 잠깐 멈춘 뒤 어깨를 천천히 끝까지 내려 충분히 늘려요."}]},
  "barbell-shrug": {"name": "바벨 슈러그", "instructions": [{"title": "준비", "text": "어깨너비보다 살짝 넓게 오버핸드 그립으로 바를 잡고 허벅지 앞에 둬요. 똑바로 서서 팔은 곧게 펴요."}, {"title": "어깨 올리기", "text": "바를 몸에 가깝게 유지하며 어깨를 귀 쪽으로 곧게 들어 올려요. 다리 반동을 쓰지 마세요."}, {"title": "내리기", "text": "맨 위에서 잠시 멈춘 뒤 어깨가 완전히 내려갈 때까지 천천히 내려요. 그립이 먼저 풀리면 스트랩을 써요."}]},
  "kelso-shrug": {"name": "켈소 슈러그", "instructions": [{"title": "준비", "text": "30–45°로 맞춘 인클라인 벤치에 엎드리고, 양손에 덤벨을 하나씩 들어 팔을 곧게 늘어뜨려요."}, {"title": "조이기", "text": "팔꿈치를 굽히지 않고 견갑골을 뒤로 당겨 모아요. 1초 동안 조인 상태를 유지해요."}, {"title": "풀기", "text": "어깨가 앞으로 뻗어질 때까지 견갑골을 천천히 벌려요."}]},
  "wrist-curl": {"name": "리스트 컬", "instructions": [{"title": "준비", "text": "벤치에 앉아 손바닥이 위를 향하게 팔뚝을 허벅지에 올리고, 손목은 무릎보다 살짝 앞으로 빼요."}, {"title": "말아 올리기", "text": "덤벨을 잡고 손목을 최대한 위로 말아 올려요. 팔뚝은 허벅지에 붙여요."}, {"title": "내리기", "text": "덤벨을 천천히 내리며 손가락 끝까지 굴러 내려가게 해 충분히 늘려요."}]},
  "reverse-curl": {"name": "리버스 컬", "instructions": [{"title": "그립 잡기", "text": "어깨너비로 바를 오버핸드 그립으로 잡고, 팔을 편 채 허벅지 앞에 둬요."}, {"title": "말아 올리기", "text": "팔꿈치를 옆구리에 고정하고 손목을 곧게 유지하며 바를 어깨까지 말아 올려요."}, {"title": "내리기", "text": "상체를 흔들지 말고 팔이 펴질 때까지 바를 천천히 내려요."}]},
  "dead-hang": {"name": "데드 행", "instructions": [{"title": "그립 잡기", "text": "철봉을 어깨너비 오버핸드 그립으로 잡고 발을 바닥에서 떼요."}, {"title": "매달리기", "text": "팔을 편 채 매달려 몸이 쭉 늘어나게 해요. 다리는 움직이지 말고 천천히 호흡해요."}, {"title": "버티기", "text": "정해진 시간 동안 바를 계속 꽉 쥐고 움직이지 않아요. 그립이 풀리기 시작하면 통제하며 내려와요."}]},
  "power-clean": {"name": "파워 클린", "instructions": [{"title": "준비", "text": "바는 발 중앙 위, 발은 골반 너비, 그립은 다리 바로 바깥쪽이에요. 골반은 무릎보다 높게, 가슴은 펴고 등은 곧게, 팔은 쭉 펴요."}, {"title": "당기기", "text": "바를 부드럽게 무릎 위까지 올린 뒤 고관절, 무릎, 발목을 폭발적으로 펴며 어깨를 으쓱해요. 바는 몸에 가깝게 유지해요."}, {"title": "받기", "text": "몸을 바 아래로 당겨 넣고 팔꿈치를 빠르게 앞으로 돌려 쿼터 스쿼트 자세에서 바를 어깨로 받아요. 똑바로 일어서요."}]},
  "hang-power-clean": {"name": "행 파워 클린", "instructions": [{"title": "준비", "text": "허벅지 바로 바깥쪽 너비로 바를 오버핸드 그립으로 잡고 똑바로 서요. 등을 곧게 편 채 바가 무릎 바로 위에 올 때까지 상체를 숙여요."}, {"title": "당기기", "text": "고관절, 무릎, 발목을 펴며 폭발적으로 점프한 뒤 어깨를 으쓱하며 바를 몸에 가깝게 끌어 올려요."}, {"title": "받기", "text": "바 아래로 빠르게 내려가 팔꿈치를 앞으로 돌리고 쿼터 스쿼트 자세에서 바를 어깨로 받아요. 일어선 뒤 다시 행 자세로 내려요."}]},
  "clean": {"name": "클린", "instructions": [{"title": "준비", "text": "바는 발 중앙 위, 발은 골반 너비, 그립은 다리 바로 바깥쪽이에요. 골반은 무릎보다 높게, 가슴은 펴고 등은 곧게 해요."}, {"title": "당기기", "text": "일정한 힘으로 밀며 바를 무릎 위까지 올린 뒤 고관절, 무릎, 발목을 폭발적으로 펴요. 바는 몸에 가깝게 유지해요."}, {"title": "받기", "text": "몸을 풀 프론트 스쿼트 자세로 끌어 내리며 팔꿈치를 높게 들고 바를 어깨로 받아요. 스쿼트 자세에서 일어서요."}]},
  "snatch": {"name": "스내치", "instructions": [{"title": "준비", "text": "섰을 때 바가 고관절 접히는 부분에 오도록 그립을 넓게 잡아요. 바는 발 중앙 위, 골반은 낮게, 가슴은 펴고 등은 곧게 해요."}, {"title": "당기기", "text": "바를 무릎 위까지 올린 뒤 고관절, 무릎, 발목을 폭발적으로 펴며 바를 몸에 가깝게 끌어 올려요."}, {"title": "받기", "text": "몸을 바 아래로 당겨 넣으며 바를 머리 위로 힘껏 밀어 올리고, 팔을 완전히 편 채 깊은 스쿼트 자세에서 받아요. 바를 머리 위에 둔 채 일어서요."}]},
  "clean-and-jerk": {"name": "클린 앤 저크", "instructions": [{"title": "클린", "text": "바를 바닥에서 당겨 올려 팔꿈치를 높게 든 프론트 스쿼트 자세에서 어깨로 받아요. 일어선 뒤 그립을 다시 잡아요."}, {"title": "딥", "text": "바를 어깨에 올린 채 상체를 곧게 세우고 무릎을 굽혀 몇 센티미터 내려간 뒤, 폭발적으로 밀어 올려요."}, {"title": "저크", "text": "몸을 바 아래로 밀어 넣으며 스플릿 자세로 들어가 팔을 완전히 편 채 머리 위에서 바를 받아요. 발을 모은 뒤 바를 내려요."}]},
  "dumbbell-thruster": {"name": "덤벨 쓰러스터", "instructions": [{"title": "준비", "text": "양손에 덤벨을 들어 어깨 위치에 두고 손바닥은 서로 마주 보게 해요. 발은 어깨너비로 벌려요."}, {"title": "스쿼트", "text": "가슴을 펴고 팔꿈치를 앞으로 둔 채 허벅지가 최소 바닥과 평행이 될 때까지 앉아요."}, {"title": "밀어 올리기", "text": "스쿼트에서 힘차게 일어나며 그 반동으로 덤벨을 한 번의 부드러운 동작으로 머리 위로 밀어 올려요. 다시 어깨로 내려요."}]},
  "box-jump": {"name": "박스 점프", "instructions": [{"title": "준비", "text": "튼튼한 박스에서 약 30cm 떨어져 서서 발을 골반 너비로 벌려요."}, {"title": "점프", "text": "팔을 뒤로 휘두르며 쿼터 스쿼트 자세로 살짝 앉았다가 박스 위로 뛰어올라요. 두 발 전체로, 무릎을 굽히며 부드럽게 착지해요."}, {"title": "내려오기", "text": "박스 위에서 완전히 일어선 뒤 한 발씩 내려와요. 다음 점프 전에 자세를 다시 잡아요."}]},
  "kettlebell-swing": {"name": "케틀벨 스윙", "instructions": [{"title": "준비", "text": "발을 골반보다 살짝 넓게 벌리고 케틀벨을 몸 약간 앞에 둬요. 상체를 숙여 양손으로 손잡이를 잡고 몸 쪽으로 기울여요."}, {"title": "스윙", "text": "케틀벨을 다리 사이로 뒤로 보낸 뒤 골반을 앞으로 강하게 튕겨 가슴 높이까지 휘둘러 올려요. 팔은 편 채 힘을 빼요."}, {"title": "컨트롤", "text": "케틀벨이 다시 떨어지게 두고 다리 사이를 지날 때 상체를 숙여요. 등은 곧게 펴고 발뒤꿈치는 바닥에 붙여요."}]},
  "farmers-walk": {"name": "파머스 워크", "instructions": [{"title": "준비", "text": "무거운 덤벨을 양손에 하나씩 데드리프트하듯 들어 올려 몸 옆에 둬요. 어깨를 뒤로 내리고 똑바로 서요."}, {"title": "걷기", "text": "정해진 시간 동안 짧고 빠른 걸음으로 걸어요. 상체는 곧게 세우고 무게가 흔들리지 않게 해요."}, {"title": "자세 유지", "text": "그립을 꽉 쥐고 복근에 힘을 주며 어느 쪽으로도 기울지 마세요. 시간이 끝나면 등을 곧게 편 채 무게를 내려놓아요."}]},
  "burpee": {"name": "버피", "instructions": [{"title": "내려가기", "text": "선 자세에서 쪼그려 앉아 발 앞 바닥에 손을 짚어요."}, {"title": "푸시업", "text": "발을 뒤로 뛰어 플랭크 자세를 만들고, 몸을 일직선으로 유지하며 푸시업을 한 뒤 발을 다시 손 쪽으로 뛰어 가져와요."}, {"title": "점프", "text": "일어서며 폭발적으로 점프하고 머리 위에서 박수를 쳐요. 부드럽게 착지하고 바로 다음 반복으로 이어가요."}]},
  "jumping-jack": {"name": "점핑 잭", "instructions": [{"title": "시작 자세", "text": "발을 모으고 팔은 몸 옆에 둔 채 똑바로 서요."}, {"title": "점프", "text": "팔을 머리 위로 휘두르며 발을 어깨보다 넓게 벌려 뛰고, 다시 뛰어서 시작 자세로 돌아와요."}, {"title": "계속하기", "text": "앞꿈치로 가볍게 뛰며 시간 내내 일정한 리듬을 유지해요. 호흡은 고르게 해요."}]},
  "high-knees": {"name": "하이 니즈", "instructions": [{"title": "시작 자세", "text": "발을 골반 너비로 벌리고 팔을 90°로 굽힌 채 똑바로 서요."}, {"title": "달리기", "text": "팔을 힘차게 흔들며 제자리에서 달리고, 무릎을 번갈아 골반 높이까지 끌어 올려요."}, {"title": "계속하기", "text": "앞꿈치로 서서 상체를 곧게 세워요. 뒤로 기대지 말고 시간 내내 빠른 속도를 유지해요."}]},
  "jump-rope": {"name": "줄넘기", "instructions": [{"title": "준비", "text": "양손에 손잡이를 하나씩 쥐고 줄은 발뒤꿈치 뒤에 둬요. 팔꿈치는 옆구리 가까이, 손은 골반 높이에 둬요."}, {"title": "점프", "text": "손목으로 줄을 돌리고 줄을 넘을 만큼만 뛰어, 앞꿈치로 부드럽게 착지해요."}, {"title": "계속하기", "text": "무릎을 살짝 굽히고 어깨에 힘을 뺀 채 시간 내내 일정한 리듬을 유지해요. 줄에 걸리면 바로 다시 시작해요."}]},
  "barbell-curl": {"name": "바벨 컬", "instructions": [{"title": "그립 잡기", "text": "똑바로 서서 어깨너비로 바를 언더핸드 그립으로 잡고 팔을 곧게 펴요."}, {"title": "말아 올리기", "text": "팔꿈치를 옆구리에 두고 상체를 고정한 채 바를 어깨 쪽으로 말아 올려요."}, {"title": "내리기", "text": "팔이 완전히 펴질 때까지 바를 천천히 내려요. 다음 반복을 시작할 때 상체를 뒤로 젖히지 마세요."}]},
  "ez-bar-curl": {"name": "EZ바 컬", "instructions": [{"title": "그립 잡기", "text": "EZ바의 안쪽 꺾인 부분을 잡아요. 손바닥은 위쪽, 살짝 안쪽을 향하게 하고 팔을 곧게 펴요."}, {"title": "말아 올리기", "text": "팔꿈치를 옆구리에 고정한 채 바를 어깨 높이까지 말아 올려요. 손목은 중립을 유지해요."}, {"title": "내리기", "text": "약 2초에 걸쳐 팔이 다시 펴질 때까지 바를 내려요."}]},
  "incline-dumbbell-curl": {"name": "인클라인 덤벨 컬", "instructions": [{"title": "준비", "text": "약 45–60°로 맞춘 벤치에 등을 기대고 앉아요. 손바닥이 앞을 향하게 하고 팔을 아래로 곧게 늘어뜨려요."}, {"title": "말아 올리기", "text": "팔꿈치가 앞으로 나가지 않게 덤벨을 말아 올려요. 머리와 등은 벤치에 붙여요."}, {"title": "내리기", "text": "팔이 다시 아래로 곧게 늘어지고 이두근이 늘어나는 느낌이 들 때까지 천천히 내려요."}]},
  "concentration-curl": {"name": "컨센트레이션 컬", "instructions": [{"title": "준비", "text": "벤치에 앉아 상체를 앞으로 숙이고 위팔 뒤쪽을 허벅지 안쪽에 고정해요."}, {"title": "말아 올리기", "text": "위팔은 움직이지 말고 덤벨을 어깨 쪽으로 말아 올려요. 맨 위에서 이두근을 조여요."}, {"title": "내리기", "text": "팔이 펴질 때까지 천천히 내려요. 모든 반복을 마친 뒤 팔을 바꿔요."}]},
  "spider-curl": {"name": "스파이더 컬", "instructions": [{"title": "준비", "text": "약 45°로 맞춘 인클라인 벤치에 가슴을 대고 엎드려요. 가슴은 벤치 위쪽 끝에 두고 팔은 아래로 곧게 늘어뜨려요."}, {"title": "말아 올리기", "text": "위팔을 수직으로 유지한 채 덤벨을 말아 올려요. 맨 위에서 강하게 조여요."}, {"title": "내리기", "text": "팔이 다시 펴질 때까지 천천히 내려요. 세트 내내 가슴을 패드에 붙여요."}]},
  "drag-curl": {"name": "드래그 컬", "instructions": [{"title": "그립 잡기", "text": "똑바로 서서 어깨너비로 바를 언더핸드 그립으로 잡고 허벅지에 붙여요."}, {"title": "끌어 올리기", "text": "팔꿈치를 뒤로 당기며 바를 몸통을 따라 가슴 아래쪽까지 끌어 올려요. 바가 몸에 닿은 상태를 유지해요."}, {"title": "내리기", "text": "팔이 펴질 때까지 바를 몸을 따라 통제하며 미끄러지듯 내려요."}]},
  "zottman-curl": {"name": "조트맨 컬", "instructions": [{"title": "말아 올리기", "text": "손바닥이 앞을 향하게 덤벨을 몸 옆에 들어요. 팔꿈치를 옆구리에 둔 채 어깨까지 말아 올려요."}, {"title": "손목 돌리기", "text": "맨 위에서 손바닥이 아래를 향하도록 손목을 돌려요. 팔꿈치는 움직이지 않아요."}, {"title": "내리기", "text": "손바닥이 아래를 향한 채 팔이 펴질 때까지 천천히 내리고, 다시 손바닥이 앞을 향하게 돌려요."}]},
  "preacher-curl": {"name": "프리처 컬", "instructions": [{"title": "준비", "text": "프리처 벤치에 앉아 겨드랑이를 패드 윗부분에 밀착해요. 언더핸드 그립으로 바를 잡아요."}, {"title": "말아 올리기", "text": "팔뚝이 거의 수직이 될 때까지 바를 말아 올려요. 위팔 뒤쪽은 패드에 붙여요."}, {"title": "내리기", "text": "팔이 거의 펴질 때까지 천천히 내려요. 바가 맨 아래로 툭 떨어지지 않게 해요."}]},
  "dumbbell-preacher-curl": {"name": "덤벨 프리처 컬", "instructions": [{"title": "준비", "text": "프리처 벤치에 앉아 한쪽 위팔 뒤쪽을 패드에 평평하게 대고, 손바닥이 위를 향하게 덤벨을 잡아요."}, {"title": "말아 올리기", "text": "팔뚝이 거의 수직이 될 때까지 덤벨을 말아 올려요. 위팔과 어깨는 움직이지 않아요."}, {"title": "내리기", "text": "팔이 거의 펴질 때까지 천천히 내린 뒤 반복해요. 세트가 끝나면 팔을 바꿔요."}]},
  "machine-curl": {"name": "바이셉스 컬 머신", "instructions": [{"title": "준비", "text": "팔꿈치가 머신의 회전축과 일직선이 되고 위팔이 패드에 평평하게 닿도록 시트를 조절해요."}, {"title": "말아 올리기", "text": "손잡이를 잡고 팔꿈치가 패드에서 뜨지 않게 어깨 쪽으로 말아 올려요."}, {"title": "내리기", "text": "이두근의 긴장을 유지하며 팔이 거의 펴질 때까지 천천히 내려요."}]},
  "cable-curl": {"name": "케이블 컬", "instructions": [{"title": "준비", "text": "하단 풀리에 스트레이트 바나 EZ바를 걸어요. 머신을 마주 보고 언더핸드 그립으로 바를 잡고 팔을 곧게 펴요."}, {"title": "말아 올리기", "text": "팔꿈치를 옆구리에 둔 채 바를 어깨 쪽으로 말아 올려요. 상체를 뒤로 젖히지 마세요."}, {"title": "내리기", "text": "케이블의 긴장을 유지하며 팔이 펴질 때까지 천천히 내려요."}]},
  "rope-hammer-curl": {"name": "로프 해머 컬", "instructions": [{"title": "준비", "text": "하단 풀리에 로프를 걸어요. 손바닥이 서로 마주 보게 로프 끝을 잡고, 팔은 곧게 펴고 팔꿈치는 옆구리에 둬요."}, {"title": "말아 올리기", "text": "엄지가 위를 향하고 위팔은 고정한 채 로프를 어깨 쪽으로 말아 올려요."}, {"title": "내리기", "text": "케이블의 긴장을 유지하며 팔이 펴질 때까지 천천히 내려요."}]},
  "bayesian-curl": {"name": "베이지안 케이블 컬", "instructions": [{"title": "준비", "text": "가장 낮은 풀리에 D 핸들을 걸고 한 손으로 잡아요. 머신을 등지고 팔이 몸 뒤로 당겨질 때까지 앞으로 걸어 나가요."}, {"title": "말아 올리기", "text": "팔꿈치를 몸통보다 살짝 뒤에 둔 채 핸들을 앞쪽 위로 말아 올려요. 어깨가 앞으로 말리지 않게 해요."}, {"title": "내리기", "text": "팔이 펴지고 이두근이 늘어나는 느낌이 들 때까지 천천히 내려요. 세트가 끝나면 팔을 바꿔요."}]},
  "rope-pushdown": {"name": "로프 푸시다운", "instructions": [{"title": "준비", "text": "상단 풀리에 로프를 걸어요. 손바닥이 서로 마주 보게 로프 끝을 잡고 팔꿈치를 옆구리에 고정해요."}, {"title": "밀어 내리기", "text": "팔이 펴질 때까지 로프를 밀어 내리고, 맨 아래에서 로프 끝을 양옆으로 벌려요."}, {"title": "되돌리기", "text": "팔뚝이 바닥과 평행보다 살짝 위에 올 때까지 로프를 천천히 올려 보내요. 팔꿈치는 움직이지 않아요."}]},
  "single-arm-pushdown": {"name": "원암 케이블 푸시다운", "instructions": [{"title": "준비", "text": "상단 풀리에 D 핸들을 걸어요. 한 손으로 잡고 그쪽 팔꿈치를 옆구리에 고정해요."}, {"title": "밀어 내리기", "text": "팔이 완전히 펴질 때까지 핸들을 밀어 내려요. 맨 아래에서 삼두근을 조여요."}, {"title": "되돌리기", "text": "팔뚝이 평행보다 살짝 위에 올 때까지 핸들을 천천히 올려 보내요. 세트가 끝나면 팔을 바꿔요."}]},
  "overhead-cable-extension": {"name": "케이블 오버헤드 익스텐션", "instructions": [{"title": "준비", "text": "하단이나 중간 풀리에 로프를 걸어요. 머신을 등지고 다리를 앞뒤로 벌려 상체를 살짝 숙인 뒤, 머리 뒤에서 로프를 잡아요."}, {"title": "펴기", "text": "팔이 펴질 때까지 앞쪽 위로 뻗어요. 팔꿈치는 머리 가까이 둬요."}, {"title": "되돌리기", "text": "손이 머리 뒤로 가고 삼두근이 늘어나는 느낌이 들 때까지 팔꿈치를 천천히 굽혀요."}]},
  "katana-extension": {"name": "카타나 익스텐션", "instructions": [{"title": "준비", "text": "하단 풀리에 D 핸들을 걸고 머신 옆으로 서요. 머신에서 먼 손으로 잡아 케이블이 몸을 가로지르게 하고, 팔꿈치를 든 채 핸들을 머리 뒤로 가져가요."}, {"title": "펴기", "text": "팔이 펴질 때까지 대각선 위 바깥쪽으로 뻗어요. 위팔은 머리 옆에 고정해요."}, {"title": "되돌리기", "text": "핸들이 다시 머리 뒤, 반대쪽 어깨 근처에 올 때까지 팔꿈치를 천천히 굽혀요. 세트가 끝나면 방향을 바꿔요."}]},
  "overhead-dumbbell-extension": {"name": "덤벨 오버헤드 익스텐션", "instructions": [{"title": "준비", "text": "등받이가 있는 벤치에 앉아 덤벨 하나를 세워 머리 위로 들어요. 양손으로 덤벨 위쪽 끝을 감싸 쥐고 팔은 곧게 펴요."}, {"title": "내리기", "text": "팔꿈치를 굽혀 덤벨을 머리 뒤로 내려요. 팔꿈치는 앞을 향하게 하고 머리 가까이 둬요."}, {"title": "펴기", "text": "팔을 펴서 덤벨을 다시 머리 위로 올려요. 허리가 젖혀지지 않게 복근에 힘을 줘요."}]},
  "dumbbell-skull-crusher": {"name": "덤벨 스컬 크러셔", "instructions": [{"title": "준비", "text": "평평한 벤치에 누워 덤벨 두 개를 어깨 위로 밀어 올려요. 손바닥은 서로 마주 보게 해요."}, {"title": "내리기", "text": "팔꿈치만 굽혀 덤벨을 머리 옆으로 내려요. 위팔은 위를 향한 채 고정해요."}, {"title": "펴기", "text": "팔을 펴서 덤벨을 다시 어깨 위로 올려요. 맨 위에서 삼두근을 조여요."}]},
  "jm-press": {"name": "JM 프레스", "instructions": [{"title": "준비", "text": "평평한 벤치에 누워 어깨너비보다 살짝 좁게 바를 잡고, 팔을 어깨 위로 곧게 펴요."}, {"title": "내리기", "text": "팔꿈치를 몸 쪽으로 붙여 발 방향을 향하게 하고 바를 턱 쪽으로 일직선으로 내려요. 팔뚝이 이두근에 닿는, 턱 바로 위 지점에서 멈춰요."}, {"title": "밀기", "text": "같은 경로를 따라 팔이 어깨 위로 곧게 펴질 때까지 바를 밀어 올려요."}]},
  "dip-machine": {"name": "시티드 딥스 머신", "instructions": [{"title": "준비", "text": "손잡이가 가슴 아래쪽 높이에서 시작하도록 시트를 조절해요. 곧게 앉아 손잡이를 잡아요."}, {"title": "밀기", "text": "팔꿈치를 몸 가까이 둔 채 팔이 펴질 때까지 손잡이를 밀어 내려요."}, {"title": "되돌리기", "text": "팔꿈치가 약 90° 굽혀질 때까지 손잡이를 천천히 올려 보내요. 어깨는 귀에서 멀어지게 아래로 내려요."}]},
  "bench-dip": {"name": "벤치 딥스", "instructions": [{"title": "준비", "text": "벤치 끝에 앉아 손가락이 앞을 향하게 골반 옆에 손을 짚어요. 엉덩이를 벤치 앞으로 빼고 발을 앞으로 걸어 내보내요."}, {"title": "내리기", "text": "팔꿈치를 곧장 뒤로 굽혀 위팔이 바닥과 거의 평행해질 때까지 골반을 내려요."}, {"title": "밀기", "text": "손바닥으로 밀어 팔을 펴요. 등은 벤치 가까이 두고 어깨는 아래로 내려요."}]},
  "diamond-push-up": {"name": "다이아몬드 푸시업", "instructions": [{"title": "손 위치", "text": "가슴 아래에 손을 두고 엄지와 검지를 맞대 다이아몬드 모양을 만들어요. 몸은 일직선으로 유지해요."}, {"title": "내리기", "text": "팔꿈치를 몸 가까이 붙인 채 가슴을 손 쪽으로 내려요."}, {"title": "밀기", "text": "팔이 펴질 때까지 밀어 올라와요. 골반이 처지지 않게 둔근을 조여요."}]},
  "dumbbell-kickback": {"name": "덤벨 트라이셉스 킥백", "instructions": [{"title": "준비", "text": "벤치에 한쪽 무릎과 한 손을 올리고 등을 곧게 펴요. 위팔을 옆구리에 붙여 바닥과 평행하게 하고 덤벨을 잡아요."}, {"title": "펴기", "text": "팔 전체가 상체와 일직선이 될 때까지 팔꿈치를 펴요. 팔뚝만 움직여요."}, {"title": "되돌리기", "text": "위팔이 처지지 않게 팔꿈치를 천천히 90°까지 다시 굽혀요. 세트가 끝나면 팔을 바꿔요."}]},
  "cable-kickback": {"name": "케이블 트라이셉스 킥백", "instructions": [{"title": "준비", "text": "하단 풀리의 케이블을 한 손으로 잡아요. 등을 곧게 편 채 상체를 숙이고, 위팔을 옆구리에 붙여 바닥과 평행하게 해요."}, {"title": "펴기", "text": "팔이 뒤로 곧게 뻗을 때까지 팔꿈치를 펴요. 위팔은 고정해요."}, {"title": "되돌리기", "text": "케이블이 느슨해지지 않게 하며 팔뚝이 아래로 곧게 늘어질 때까지 팔꿈치를 천천히 굽혀요. 세트가 끝나면 팔을 바꿔요."}]},
  "triceps-extension-machine": {"name": "트라이셉스 익스텐션 머신", "instructions": [{"title": "준비", "text": "팔꿈치가 머신의 회전축과 일직선이 되도록 시트를 조절하고 위팔을 패드에 올려요."}, {"title": "펴기", "text": "팔이 펴질 때까지 손잡이를 밀어요. 팔꿈치는 패드에 붙여요."}, {"title": "되돌리기", "text": "삼두근의 긴장을 유지하며 팔꿈치가 약 90° 굽혀질 때까지 손잡이를 천천히 되돌려요."}]},
  "side-plank": {"name": "사이드 플랭크", "instructions": [{"title": "준비", "text": "옆으로 누워 팔꿈치를 어깨 아래에 두고 두 발을 포개요."}, {"title": "들어 올리기", "text": "머리부터 발뒤꿈치까지 몸이 일직선이 될 때까지 골반을 들어 올려요. 골반이 앞으로 돌아가지 않게 위아래로 포갠 상태를 유지해요."}, {"title": "버티기", "text": "일정하게 호흡하며 골반이 처지지 않게 버텨요. 그다음 방향을 바꿔 같은 시간 동안 버텨요."}]},
  "hollow-hold": {"name": "할로우 홀드", "instructions": [{"title": "준비", "text": "등을 대고 누워 팔을 머리 위로 뻗어요. 허리를 바닥에 단단히 붙여요."}, {"title": "들어 올리기", "text": "어깨, 팔, 곧게 편 다리를 바닥에서 몇 센티미터 들어 올려 몸이 얕은 바나나 모양이 되게 해요."}, {"title": "버티기", "text": "일정하게 호흡하며 버텨요. 허리가 뜨면 무릎을 굽히거나 팔을 앞으로 가져와요."}]},
  "l-sit": {"name": "L-싯", "instructions": [{"title": "준비", "text": "패럴렛, 딥스 바 또는 엉덩이 옆 바닥에 손을 짚어요. 팔을 곧게 펴서 고정하고 어깨를 아래로 눌러요."}, {"title": "들어 올리기", "text": "다리를 곧게 편 채 앞으로 들어 바닥과 평행하게 만들어요. 발끝을 뻗고 허벅지에 힘을 줘요."}, {"title": "버티기", "text": "호흡을 일정하게 유지하며 가슴을 편 채 버텨요. 다리가 처지면 무릎을 굽혀 자세를 유지해요."}]},
  "crunch": {"name": "크런치", "instructions": [{"title": "준비", "text": "무릎을 굽히고 발바닥을 바닥에 붙인 채 누워요. 손끝은 귀 뒤에 가볍게 대요."}, {"title": "크런치", "text": "복근을 수축해 어깨를 바닥에서 말아 올려요. 허리는 바닥에 붙이고 목을 당기지 마세요."}, {"title": "내리기", "text": "어깨뼈가 바닥에 닿을 때까지 천천히 내린 뒤 다음 반복을 시작해요."}]},
  "sit-up": {"name": "싯업", "instructions": [{"title": "준비", "text": "무릎을 굽히고 발바닥을 바닥에 붙인 채 누워요. 필요하면 패드 아래에 발을 고정해요. 팔은 가슴 앞에서 교차해요."}, {"title": "일어나기", "text": "척추를 한 마디씩 말아 올리며 가슴이 허벅지에 가까워질 때까지 상체를 일으켜요."}, {"title": "내리기", "text": "어깨가 바닥에 닿을 때까지 천천히 굴러 내려가요. 반동을 얻으려고 바닥에서 튕기지 마세요."}]},
  "decline-sit-up": {"name": "디클라인 싯업", "instructions": [{"title": "준비", "text": "디클라인 벤치의 패드 아래에 발을 걸고 뒤로 누워요. 팔을 교차하거나 원판을 가슴에 대고 잡아요."}, {"title": "일어나기", "text": "원판을 가슴에 밀착한 채 상체가 거의 수직이 될 때까지 말아 올려요."}, {"title": "내리기", "text": "허리가 벤치에 닿을 때까지 천천히 내려가요. 다음 반복을 위해 뒤로 털썩 떨어지지 마세요."}]},
  "bicycle-crunch": {"name": "바이시클 크런치", "instructions": [{"title": "준비", "text": "누워서 손을 머리 뒤에 가볍게 대고 어깨와 발을 바닥에서 들어요."}, {"title": "비틀기", "text": "한쪽 무릎을 가슴 쪽으로 당기면서 반대쪽 팔꿈치를 무릎 쪽으로 돌리고, 다른 쪽 다리는 쭉 뻗어요."}, {"title": "번갈아 하기", "text": "천천히 페달을 밟듯 좌우를 바꿔요. 팔로 당기지 말고 몸통을 회전해요. 허리는 바닥에 붙여요."}]},
  "reverse-crunch": {"name": "리버스 크런치", "instructions": [{"title": "준비", "text": "팔을 몸 옆에 두고 누워요. 고관절과 무릎을 90°로 굽히고 정강이를 바닥과 평행하게 해요."}, {"title": "말아 올리기", "text": "복근으로 엉덩이를 바닥에서 말아 올리며 무릎을 가슴 쪽으로 가져와요. 다리를 휘두르지 마세요."}, {"title": "내리기", "text": "정강이가 다시 평행해질 때까지 엉덩이를 천천히 바닥으로 내려요."}]},
  "ab-crunch-machine": {"name": "앱 크런치 머신", "instructions": [{"title": "준비", "text": "패드가 가슴이나 어깨에 닿도록 시트를 조절해요. 손잡이를 잡고 발을 고정해요."}, {"title": "크런치", "text": "복근을 수축해 상체를 앞쪽 아래로 말아요. 팔로 당기거나 다리로 밀지 마세요."}, {"title": "돌아오기", "text": "중량판이 닿지 않게 하면서 상체가 다시 세워질 때까지 천천히 돌아와요."}]},
  "cable-crunch": {"name": "케이블 크런치", "instructions": [{"title": "준비", "text": "로프를 케이블 상단에 연결하고 머신을 바라보며 무릎을 꿇어요. 로프 끝을 머리 옆에서 잡아요."}, {"title": "크런치", "text": "척추를 둥글게 말아 갈비뼈를 골반 쪽으로 당겨요. 엉덩이는 고정하고 발뒤꿈치 위로 주저앉지 마세요."}, {"title": "돌아오기", "text": "케이블의 장력을 유지하며 등이 다시 펴질 때까지 천천히 풀어요."}]},
  "hanging-leg-raise": {"name": "행잉 레그 레이즈", "instructions": [{"title": "매달리기", "text": "철봉에 오버핸드 그립으로 매달려요. 팔은 곧게 펴고 어깨에 살짝 힘을 줘요."}, {"title": "올리기", "text": "다리를 곧게 편 채 최소한 바닥과 평행할 때까지 올리고, 맨 위에서 골반을 위로 말아 올려요."}, {"title": "내리기", "text": "몸이 흔들리지 않게 다리를 천천히 내려요. 다음 반복 전에 아래에서 잠깐 멈춰요."}]},
  "hanging-knee-raise": {"name": "행잉 니 레이즈", "instructions": [{"title": "매달리기", "text": "철봉에 오버핸드 그립으로 매달려요. 팔은 곧게 펴고 다리는 모아요."}, {"title": "올리기", "text": "무릎을 가슴 쪽으로 당겨 올리고, 맨 위에서 골반을 말아 올려요. 몸이 흔들리지 않게 해요."}, {"title": "내리기", "text": "다음 반복 전에 다리가 다시 곧게 늘어질 때까지 천천히 내려요."}]},
  "toes-to-bar": {"name": "토즈 투 바", "instructions": [{"title": "매달리기", "text": "어깨너비보다 약간 넓은 오버핸드 그립으로 철봉에 매달려요. 팔은 곧게 펴요."}, {"title": "올리기", "text": "팔을 편 채 바를 아래로 누르고 복근에 힘을 준 뒤, 발끝이 양손 사이의 바에 닿을 때까지 발을 들어 올려요."}, {"title": "내리기", "text": "다리를 통제하며 내리고, 다음 반복 전에 흔들림을 멈춰요."}]},
  "captains-chair-leg-raise": {"name": "캡틴스 체어 레그 레이즈", "instructions": [{"title": "준비", "text": "캡틴스 체어 패드에 전완을 올리고 손잡이를 잡은 뒤 등을 등받이에 붙여요."}, {"title": "올리기", "text": "등을 패드에 붙인 채 다리를 곧게 펴서 바닥과 평행할 때까지 올려요."}, {"title": "내리기", "text": "다리가 곧게 아래로 늘어질 때까지 천천히 내려요. 반동을 이용해 다음 반복으로 넘어가지 마세요."}]},
  "lying-leg-raise": {"name": "라잉 레그 레이즈", "instructions": [{"title": "준비", "text": "다리를 곧게 펴고 누워 손을 엉덩이 아래나 몸 옆에 둬요."}, {"title": "올리기", "text": "다리를 곧게 편 채 천장을 향할 때까지 들어 올려요. 허리는 바닥에 눌러 붙여요."}, {"title": "내리기", "text": "다리를 천천히 내리고 발뒤꿈치가 바닥에 닿기 직전에 멈춰요."}]},
  "russian-twist": {"name": "러시안 트위스트", "instructions": [{"title": "준비", "text": "무릎을 굽히고 발뒤꿈치를 바닥에 댄 채 앉아요. 상체를 약 45° 뒤로 기울이고 가슴 앞에서 두 손을 모아요."}, {"title": "비틀기", "text": "손이 엉덩이 옆에 올 때까지 상체를 한쪽으로 돌린 뒤 반대쪽으로 돌려요. 팔만 움직이지 말고 갈비뼈부터 돌려요."}, {"title": "자세 유지", "text": "가슴을 펴고 등을 곧게 유지해요. 강도를 높이려면 발을 바닥에서 들어요."}]},
  "dumbbell-side-bend": {"name": "덤벨 사이드 벤드", "instructions": [{"title": "준비", "text": "한 손에 덤벨을 들어 몸 옆에 두고 똑바로 서요. 발은 골반 너비로 벌리고 다른 손은 허리에 올려요."}, {"title": "굽히기", "text": "덤벨이 허벅지를 따라 내려가도록 덤벨 쪽으로 옆구리를 굽혀요. 앞이나 뒤로 기울이지 마세요."}, {"title": "돌아오기", "text": "반대쪽 복사근으로 몸을 다시 세워요. 세트가 끝나면 반대쪽을 해요."}]},
  "torso-rotation-machine": {"name": "토르소 로테이션 머신", "instructions": [{"title": "준비", "text": "머신에 앉아 엉덩이를 고정하고 가슴을 패드에 대요. 시작 각도를 한쪽으로 맞춰요."}, {"title": "회전하기", "text": "엉덩이는 정면을 향한 채 복사근으로 상체를 반대쪽으로 돌려요."}, {"title": "돌아오기", "text": "시작 자세로 천천히 돌아와요. 모든 반복을 마치면 머신을 반대쪽으로 맞춰요."}]},
  "cable-woodchop": {"name": "케이블 우드찹", "instructions": [{"title": "준비", "text": "D 핸들을 케이블 상단에 연결하고 머신 옆으로 서요. 두 손으로 핸들을 잡고 팔을 도르래 쪽으로 뻗어요."}, {"title": "당기기", "text": "핸들을 대각선 아래로 반대쪽 엉덩이까지 당겨요. 몸통을 돌리면서 뒷발도 함께 돌려요."}, {"title": "돌아오기", "text": "같은 경로를 따라 핸들이 천천히 올라가게 해요. 세트가 끝나면 반대쪽을 해요."}]},
  "pallof-press": {"name": "팔로프 프레스", "instructions": [{"title": "준비", "text": "D 핸들을 가슴 높이에 연결하고 머신 옆으로 서요. 발은 어깨너비로 벌리고 두 손으로 핸들을 가슴 앞에 잡아요."}, {"title": "밀기", "text": "핸들을 가슴 앞으로 곧게 밀어내고, 케이블이 몸을 돌리려는 힘에 버텨요. 1초간 유지해요."}, {"title": "돌아오기", "text": "엉덩이와 어깨를 정면으로 유지한 채 핸들을 통제하며 가슴으로 가져와요. 세트가 끝나면 반대쪽을 해요."}]},
  "ab-wheel-rollout": {"name": "앱 휠 롤아웃", "instructions": [{"title": "준비", "text": "매트에 무릎을 꿇고 어깨 아래에서 앱 휠을 잡아요. 복근에 힘을 주고 골반을 살짝 말아요."}, {"title": "밀어내기", "text": "허리가 처지지 않는 범위에서 최대한 멀리 휠을 천천히 굴려요."}, {"title": "당겨 오기", "text": "엉덩이가 아닌 복근으로 휠을 무릎 쪽으로 당겨 와요. 팔은 곧게 유지해요."}]},
  "mountain-climber": {"name": "마운틴 클라이머", "instructions": [{"title": "준비", "text": "손을 어깨 아래에 두고 몸을 일직선으로 만든 하이 플랭크 자세로 시작해요."}, {"title": "무릎 당기기", "text": "한쪽 무릎을 가슴 쪽으로 힘차게 당긴 뒤, 달리듯 리듬감 있게 다리를 빠르게 바꿔요."}, {"title": "자세 유지", "text": "엉덩이를 어깨 높이로 유지하고 손은 바닥에 고정해요. 엉덩이가 솟을 것 같으면 속도를 늦춰요."}]},
  "dead-bug": {"name": "데드버그", "instructions": [{"title": "준비", "text": "누워서 팔을 천장으로 뻗고 고관절과 무릎을 90°로 굽혀요. 허리는 바닥에 눌러 붙여요."}, {"title": "뻗기", "text": "한쪽 팔을 머리 위로 천천히 내리면서 반대쪽 다리를 펴, 둘 다 바닥 바로 위에 떠 있게 해요."}, {"title": "반대쪽", "text": "시작 자세로 돌아와 반대쪽도 반복해요. 허리를 바닥에 붙이고 뻗을 때 숨을 내쉬어요."}]},
  "bird-dog": {"name": "버드독", "instructions": [{"title": "준비", "text": "손은 어깨 아래, 무릎은 엉덩이 아래에 두고 네발 자세를 취해요. 등은 평평하게 유지해요."}, {"title": "뻗기", "text": "한쪽 팔은 앞으로, 반대쪽 다리는 뒤로 뻗어 몸통과 일직선이 되게 해요. 1초간 유지해요."}, {"title": "반대쪽", "text": "천천히 돌아와 반대쪽도 반복해요. 골반을 수평으로 유지하고 허리를 젖히지 마세요."}]},
  "paused-squat": {"name": "포즈 스쿼트", "instructions": [{"title": "준비", "text": "바를 등 상부에 얹고 랙에서 빼요. 발은 어깨너비, 발끝은 살짝 바깥으로 향하게 하고 복압을 강하게 잡아요."}, {"title": "멈추기", "text": "허벅지가 최소한 평행이 될 때까지 앉고, 긴장을 유지한 채 가장 낮은 지점에서 2초간 멈춰요."}, {"title": "일어나기", "text": "튕기지 말고 발 전체로 밀며 가장 낮은 지점에서 힘차게 일어나요."}]},
  "box-squat": {"name": "박스 스쿼트", "instructions": [{"title": "박스 높이", "text": "앉았을 때 허벅지가 거의 평행이 되는 높이로 박스를 뒤에 놓아요. 평소보다 발을 조금 넓게 벌리고 서요."}, {"title": "앉기", "text": "엉덩이를 뒤로 빼며 통제된 속도로 내려가 박스에 가볍게 앉아요. 복압을 유지하고 힘을 풀지 마세요."}, {"title": "일어나기", "text": "몸을 흔들거나 튕기지 말고 발로 바닥을 밀어 폭발적으로 일어나요."}]},
  "front-squat": {"name": "프론트 스쿼트", "instructions": [{"title": "바 걸치기", "text": "바를 목 가까이 전면 삼각근 위에 얹어요. 팔꿈치는 높이 들고, 손끝을 바 아래에 넣거나 팔을 교차해요."}, {"title": "내려가기", "text": "상체를 세우고 팔꿈치를 든 채 수직으로 앉아요. 무릎은 발끝 위로 앞으로 나가게 해요."}, {"title": "일어나기", "text": "발 전체로 밀어 올리고, 바가 앞으로 굴러가지 않게 팔꿈치부터 들어 올려요."}]},
  "safety-bar-squat": {"name": "세이프티 바 스쿼트", "instructions": [{"title": "준비", "text": "패드가 있는 요크를 등 상부에 얹고 손잡이를 앞에서 잡아요. 발은 어깨너비로 벌려요."}, {"title": "내려가기", "text": "가슴을 편 채 다리 사이로 내려앉아요. 바 때문에 몸이 앞으로 쏠리지 않게 손잡이를 아래로 당겨요."}, {"title": "일어나기", "text": "등 상부를 패드에 단단히 붙인 채 발 전체로 밀어 일어서요."}]},
  "smith-squat": {"name": "스미스 머신 스쿼트", "instructions": [{"title": "준비", "text": "바를 등 상부에 얹고 발을 어깨너비로 벌려 바보다 약간 앞에 둬요."}, {"title": "내려가기", "text": "바를 돌려 고리에서 빼고, 등을 곧게 편 채 허벅지가 최소한 평행이 될 때까지 내려가요."}, {"title": "일어나기", "text": "발 전체로 밀어 올리고, 마지막 반복 후 바를 돌려 고리에 다시 걸어요."}]},
  "goblet-squat": {"name": "고블릿 스쿼트", "instructions": [{"title": "잡기", "text": "덤벨 하나를 세로로 세워 두 손으로 가슴에 붙여 잡아요. 팔꿈치는 아래를 향해요."}, {"title": "내려가기", "text": "가슴을 편 채 양발 뒤꿈치 사이로 앉아, 팔꿈치가 무릎 안쪽에 살짝 닿을 때까지 내려가요."}, {"title": "일어나기", "text": "덤벨을 가슴 가까이 유지하며 발 전체로 밀어 일어서요."}]},
  "sumo-squat": {"name": "스모 스쿼트", "instructions": [{"title": "스탠스", "text": "발을 어깨너비보다 훨씬 넓게 벌리고 발끝을 약 45° 바깥으로 돌려요. 덤벨 하나를 다리 사이로 들어요."}, {"title": "내려가기", "text": "상체를 세운 채 수직으로 내려가며 무릎을 발끝 방향으로 밀어 벌려요."}, {"title": "일어나기", "text": "발뒤꿈치로 밀어 일어서고, 맨 위에서 둔근을 조여요."}]},
  "bodyweight-squat": {"name": "맨몸 스쿼트", "instructions": [{"title": "스탠스", "text": "발은 어깨너비, 발끝은 살짝 바깥으로 향하게 해요. 균형을 위해 팔을 앞으로 뻗어요."}, {"title": "내려가기", "text": "허벅지가 최소한 평행이 될 때까지 엉덩이를 뒤로 빼며 앉아요. 발뒤꿈치는 바닥에 붙이고 가슴은 펴요."}, {"title": "일어서기", "text": "발 전체로 밀어 일어서고 맨 위에서 둔근을 조여요. 일정한 리듬을 유지해요."}]},
  "jump-squat": {"name": "점프 스쿼트", "instructions": [{"title": "스탠스", "text": "발을 어깨너비로 벌리고 서서 손은 가슴 앞에 두거나 머리 뒤에 대요."}, {"title": "낮추기", "text": "원하면 팔을 뒤로 휘두르며 쿼터에서 하프 스쿼트 깊이까지 빠르게 내려가요."}, {"title": "점프", "text": "수직으로 폭발적으로 뛰어오른 뒤 발 앞꿈치로 부드럽게 착지하고 바로 다음 반복으로 내려가요."}]},
  "reverse-hack-squat": {"name": "리버스 핵 스쿼트", "instructions": [{"title": "준비", "text": "가슴을 등 패드에 대고 머신을 마주 본 채 어깨를 패드 아래에 넣어요. 발판 위에 발을 골반 너비로 둬요."}, {"title": "내려가기", "text": "안전 장치를 풀고 엉덩이를 뒤쪽 아래로 빼며 앉아요. 상체는 패드를 따라 앞으로 기울여요."}, {"title": "일어나기", "text": "발뒤꿈치로 밀고 둔근을 조여 올라오되, 맨 위에서 무릎을 잠그지 마세요."}]},
  "pendulum-squat": {"name": "펜듈럼 스쿼트", "instructions": [{"title": "준비", "text": "발판에 올라 등을 패드에 붙이고 어깨를 패드 아래에 넣어요. 발은 골반 너비로 발판 가운데에 둬요."}, {"title": "내려가기", "text": "잠금장치를 풀고 패드가 호를 그리며 내려가게 해요. 발뒤꿈치를 붙인 채 최대한 깊이 앉아요."}, {"title": "일어나기", "text": "발 전체로 밀어 다시 올라가고, 맨 위에서 무릎을 살짝 굽힌 상태를 유지해요."}]},
  "belt-squat": {"name": "벨트 스쿼트", "instructions": [{"title": "벨트 착용", "text": "힙 벨트를 착용하고 머신의 체인이나 스트랩에 연결해요. 발판 위에 발을 어깨너비로 벌리고 서요."}, {"title": "내려가기", "text": "균형을 위해 손잡이를 가볍게 잡고 레버를 푼 뒤 상체를 세운 채 앉아요."}, {"title": "일어나기", "text": "발 전체로 밀어 일어서요. 무게가 엉덩이에 걸리기 때문에 척추에는 부하가 실리지 않아요."}]},
  "single-leg-press": {"name": "싱글 레그 프레스", "instructions": [{"title": "발 위치", "text": "한 발을 발판 가운데에 골반과 일직선으로 놓아요. 다른 발은 바닥이나 프레임에 둬요."}, {"title": "내리기", "text": "안전 장치를 풀고 엉덩이를 시트에 붙인 채 무릎을 약 90°까지 천천히 굽혀요."}, {"title": "밀기", "text": "무릎을 잠그지 말고 발 전체로 밀어요. 모든 반복을 마치면 다리를 바꿔요."}]},
  "walking-lunge": {"name": "워킹 런지", "instructions": [{"title": "서기", "text": "양손에 덤벨을 들어 몸 옆에 두고 똑바로 서요. 앞에 공간을 충분히 확보해요."}, {"title": "내딛기", "text": "앞으로 크게 한 걸음 내딛고 뒷무릎을 바닥 바로 위까지 내려요. 앞 정강이는 거의 수직이 되게 해요."}, {"title": "걷기", "text": "앞발 뒤꿈치로 밀고 뒷발을 그대로 앞으로 가져와 다음 걸음을 내디뎌요. 다리를 번갈아 해요."}]},
  "reverse-lunge": {"name": "리버스 런지", "instructions": [{"title": "서기", "text": "발을 골반 너비로 벌리고 양손에 덤벨을 들어 몸 옆에 둔 채 똑바로 서요."}, {"title": "뒤로 딛기", "text": "뒤로 크게 한 걸음 물러서며 상체를 세운 채 뒷무릎을 바닥 쪽으로 내려요."}, {"title": "돌아오기", "text": "앞발 뒤꿈치로 밀어 뒷발을 시작 위치로 가져와요. 다리를 번갈아 하거나 한쪽씩 해요."}]},
  "smith-lunge": {"name": "스미스 머신 런지", "instructions": [{"title": "준비", "text": "바를 등 상부에 얹고 고리에서 뺀 뒤, 한 발은 앞에 두고 뒷발 뒤꿈치는 든 스플릿 스탠스를 취해요."}, {"title": "내리기", "text": "앞 허벅지가 거의 평행이 될 때까지 뒷무릎을 바닥 쪽으로 곧게 내려요."}, {"title": "일어나기", "text": "앞발로 밀어 올라오되 무릎을 끝까지 펴서 잠그지는 마세요. 모든 반복을 마치면 다리를 바꿔요."}]},
  "bulgarian-split-squat": {"name": "불가리안 스플릿 스쿼트", "instructions": [{"title": "준비", "text": "벤치 앞으로 한 걸음 정도 떨어져 서서 뒷발 등을 벤치에 올려요. 양손에 덤벨을 들어요."}, {"title": "내리기", "text": "앞발 뒤꿈치를 바닥에 붙인 채 앞 허벅지가 거의 평행이 될 때까지 수직으로 내려가요."}, {"title": "일어나기", "text": "앞발로 밀어 올라와요. 모든 반복을 마치면 다리를 바꿔요."}]},
  "split-squat": {"name": "스플릿 스쿼트", "instructions": [{"title": "스탠스", "text": "양손에 덤벨을 들고 앞뒤로 넓게 스플릿 스탠스를 취해요. 앞발은 바닥에 붙이고 뒷발 뒤꿈치는 들어요."}, {"title": "내리기", "text": "발을 움직이지 말고 뒷무릎이 바닥에 거의 닿을 때까지 수직으로 내려요."}, {"title": "일어나기", "text": "상체를 세운 채 앞발로 밀어 올라와요. 모든 반복을 마치면 다리를 바꿔요."}]},
  "step-up": {"name": "스텝업", "instructions": [{"title": "준비", "text": "양손에 덤벨을 들고 무릎 높이의 박스나 벤치를 마주 보고 서요. 한 발 전체를 위에 올려요."}, {"title": "올라서기", "text": "박스 위에 올린 발의 뒤꿈치로 밀어 올라서요. 뒷발로 바닥을 차지 마세요."}, {"title": "내리기", "text": "같은 다리로 천천히 내려와요. 모든 반복을 마치면 반대쪽을 해요."}]},
  "sissy-squat": {"name": "시시 스쿼트", "instructions": [{"title": "준비", "text": "균형을 위해 기둥이나 시시 스쿼트 벤치를 잡고 발 앞꿈치로 올라서요. 발은 골반 너비로 벌려요."}, {"title": "뒤로 기울이기", "text": "몸을 뒤로 기울이면서 무릎을 앞쪽 아래로 밀어요. 무릎부터 어깨까지 일직선을 유지해요."}, {"title": "돌아오기", "text": "대퇴사두근을 조여 몸을 다시 끌어올려요. 동작 내내 고관절은 편 상태를 유지해요."}]},
  "wall-sit": {"name": "월 싯", "instructions": [{"title": "준비", "text": "벽에 등을 붙이고 서서 발을 골반 너비로 벌린 채 앞으로 옮겨요."}, {"title": "버티기", "text": "허벅지가 바닥과 평행할 때까지 미끄러져 내려가요. 무릎은 발목 위에 두고 정해진 시간 동안 버텨요."}, {"title": "자세", "text": "등과 머리를 벽에 붙이고 손은 허벅지에서 떼요. 호흡은 일정하게 해요."}]},
  "dumbbell-romanian-deadlift": {"name": "덤벨 루마니안 데드리프트", "instructions": [{"title": "시작 자세", "text": "양손에 덤벨을 들어 허벅지 앞에 두고 무릎을 살짝 굽힌 채 똑바로 서요."}, {"title": "힙 힌지", "text": "엉덩이를 뒤로 빼면서 햄스트링이 늘어나는 느낌이 들 때까지 덤벨을 다리에 가깝게 내려요."}, {"title": "돌아오기", "text": "엉덩이를 앞으로 밀어 일어서고 둔근을 조여요. 동작 내내 등은 곧게 유지해요."}]},
  "single-leg-romanian-deadlift": {"name": "싱글 레그 루마니안 데드리프트", "instructions": [{"title": "시작 자세", "text": "무릎을 살짝 굽혀 한 다리로 서고, 반대쪽 손에 덤벨을 들어요."}, {"title": "힙 힌지", "text": "들린 다리를 뒤로 뻗으면서 고관절을 접어 상체가 바닥과 거의 평행해질 때까지 앞으로 숙여요. 골반은 정면을 유지해요."}, {"title": "돌아오기", "text": "디딘 쪽 엉덩이를 앞으로 밀어 다시 똑바로 서요. 모든 반복을 마치면 다리를 바꿔요."}]},
  "stiff-leg-deadlift": {"name": "스티프 레그 데드리프트", "instructions": [{"title": "시작 자세", "text": "바를 발 중앙 위에 두고 다리를 거의 편 채 서요. 무릎은 살짝만 굽혀요."}, {"title": "내리기", "text": "등을 곧게 편 채 고관절을 접어 햄스트링이 완전히 늘어날 때까지 바를 바닥 쪽으로 내려요."}, {"title": "들어 올리기", "text": "무릎을 거의 편 채 엉덩이를 앞으로 밀어 일어서요. 바는 다리에 가깝게 유지해요."}]},
  "good-morning": {"name": "굿모닝", "instructions": [{"title": "준비", "text": "스쿼트처럼 바를 등 상부에 얹어요. 발은 골반 너비로 벌리고 무릎은 살짝 굽혀요."}, {"title": "힙 힌지", "text": "엉덩이를 뒤로 빼면서 등을 곧게 편 채 상체를 숙여요. 거의 평행이 되거나 햄스트링이 강하게 당길 때까지 내려가요."}, {"title": "돌아오기", "text": "엉덩이를 앞으로 밀어 다시 일어서요. 지렛대가 길어 허리에 부하가 크게 걸리니 가볍게 시작해요."}]},
  "cable-pull-through": {"name": "케이블 풀 스루", "instructions": [{"title": "준비", "text": "로프를 케이블 하단에 연결하고 등지고 서서 다리 사이로 로프를 잡아요. 몇 걸음 앞으로 나와 발을 골반보다 넓게 벌려요."}, {"title": "힙 힌지", "text": "엉덩이를 뒤로 빼며 로프가 손을 다리 사이 뒤쪽으로 당기게 해요. 무릎은 살짝 굽히고 등은 곧게 유지해요."}, {"title": "일어서기", "text": "엉덩이를 앞으로 밀어 똑바로 서고 맨 위에서 둔근을 강하게 조여요. 팔로 당기지 마세요."}]},
  "lying-leg-curl": {"name": "라잉 레그 컬", "instructions": [{"title": "준비", "text": "엎드려 누워 무릎이 패드 끝을 살짝 벗어나 회전축과 일직선이 되게 하고, 롤러는 발뒤꿈치 바로 위에 오게 해요."}, {"title": "당기기", "text": "엉덩이를 패드에 붙인 채 발뒤꿈치를 둔근 쪽으로 최대한 당겨요."}, {"title": "내리기", "text": "중량판이 닿지 않게 하면서 다리가 거의 펴질 때까지 천천히 내려요."}]},
  "seated-leg-curl": {"name": "시티드 레그 컬", "instructions": [{"title": "준비", "text": "무릎을 회전축과 일직선으로 맞춰 앉아요. 아래 롤러는 발뒤꿈치 바로 위에 두고 허벅지 패드를 단단히 고정해요."}, {"title": "당기기", "text": "상체를 살짝 앞으로 기울이며 발뒤꿈치를 시트 아래 뒤쪽으로 최대한 당겨요."}, {"title": "돌아오기", "text": "다리가 거의 펴질 때까지 롤러가 천천히 올라오게 하고, 위에서도 긴장을 유지해요."}]},
  "standing-leg-curl": {"name": "스탠딩 레그 컬", "instructions": [{"title": "준비", "text": "머신을 마주 보고 서서 엉덩이를 패드에 대고, 운동하는 다리의 발뒤꿈치 바로 위에 롤러를 둬요."}, {"title": "당기기", "text": "허벅지는 수직으로, 엉덩이는 패드에 붙인 채 발뒤꿈치를 둔근 쪽으로 당겨 올려요."}, {"title": "내리기", "text": "다리가 거의 펴질 때까지 천천히 내려요. 모든 반복을 마치면 다리를 바꿔요."}]},
  "nordic-curl": {"name": "노르딕 햄스트링 컬", "instructions": [{"title": "준비", "text": "패드 위에 무릎을 꿇고 파트너나 고정 패드로 발뒤꿈치를 눌러 고정해요. 무릎부터 머리까지 몸을 곧게 유지해요."}, {"title": "내리기", "text": "햄스트링으로 제동하며 최대한 천천히 앞으로 기울어요. 고관절은 편 상태를 유지해요."}, {"title": "돌아오기", "text": "더 버틸 수 없으면 손으로 몸을 받친 뒤, 가볍게 밀어내며 다시 말아 올라와요."}]},
  "glute-ham-raise": {"name": "글루트 햄 레이즈", "instructions": [{"title": "준비", "text": "롤러 사이에 발을 고정하고 무릎은 패드 바로 뒤에 둬요. 몸을 곧게 세운 상태로 시작해요."}, {"title": "내리기", "text": "고관절을 편 채 몸이 바닥과 평행해질 때까지 통제하며 앞으로 내려가요."}, {"title": "올라오기", "text": "발끝으로 발판을 누르고 둔근을 조인 채 햄스트링으로 몸을 다시 끌어올려요."}]},
  "hip-thrust": {"name": "바벨 힙 쓰러스트", "instructions": [{"title": "준비", "text": "등 상부를 벤치에 기대고 앉아 패드를 감은 바를 골반 위로 굴려 올려요. 발은 바닥에 붙이고 골반 너비로 벌려요."}, {"title": "들어 올리기", "text": "발뒤꿈치로 밀어 어깨부터 무릎까지 일직선이 될 때까지 엉덩이를 들어 올려요. 정강이는 수직이 되게 해요."}, {"title": "락아웃", "text": "턱을 당긴 채 맨 위에서 둔근을 강하게 조인 뒤, 통제하며 내려요."}]},
  "hip-thrust-machine": {"name": "힙 쓰러스트 머신", "instructions": [{"title": "준비", "text": "등 상부를 패드에 대고 머신에 앉아 벨트나 패드를 골반 위에 걸쳐요. 발은 바닥에 붙이고 골반 너비로 벌려요."}, {"title": "밀어 올리기", "text": "발뒤꿈치로 밀어 어깨부터 무릎까지 일직선이 될 때까지 고관절을 펴요."}, {"title": "내리기", "text": "맨 위에서 1초간 둔근을 조인 뒤, 무게를 내려놓지 말고 천천히 내려요."}]},
  "glute-bridge": {"name": "글루트 브리지", "instructions": [{"title": "준비", "text": "무릎을 굽히고 발바닥을 바닥에 붙인 채 골반 너비로 벌리고 누워요. 원하면 골반 위에 무게를 올려요."}, {"title": "들어 올리기", "text": "발뒤꿈치로 밀어 어깨부터 무릎까지 일직선이 될 때까지 엉덩이를 들어 올려요."}, {"title": "내리기", "text": "맨 위에서 1초간 둔근을 조인 뒤, 엉덩이가 바닥에 거의 닿을 때까지 천천히 내려요."}]},
  "single-leg-glute-bridge": {"name": "싱글 레그 글루트 브리지", "instructions": [{"title": "준비", "text": "누워서 한 발은 엉덩이 가까이 바닥에 붙이고, 다른 다리는 곧게 펴거나 가슴 쪽으로 당겨요."}, {"title": "들어 올리기", "text": "바닥에 닿은 발의 뒤꿈치로 밀어 골반이 수평이 되고 무릎과 일직선이 될 때까지 엉덩이를 들어 올려요."}, {"title": "내리기", "text": "골반이 기울어지지 않게 천천히 내려요. 모든 반복을 마치면 다리를 바꿔요."}]},
  "cable-glute-kickback": {"name": "케이블 글루트 킥백", "instructions": [{"title": "준비", "text": "케이블 하단에 연결한 발목 스트랩을 한쪽 다리에 착용해요. 머신을 마주 보고 프레임을 잡은 채 상체를 살짝 숙여요."}, {"title": "킥백", "text": "허리를 젖히지 말고 둔근을 조여 다리를 뒤쪽 약간 위로 밀어내요."}, {"title": "돌아오기", "text": "다리를 천천히 통제하며 앞으로 가져와요. 모든 반복을 마치면 다리를 바꿔요."}]},
  "glute-kickback-machine": {"name": "글루트 킥백 머신", "instructions": [{"title": "준비", "text": "가슴이나 전완을 패드에 올리고 한 발을 발판에 붙여요. 디딘 다리는 살짝 굽혀요."}, {"title": "밀기", "text": "등을 젖히지 말고 둔근을 조여 고관절이 완전히 펴질 때까지 발판을 뒤쪽 위로 밀어요."}, {"title": "돌아오기", "text": "무릎이 가슴 가까이 올 때까지 발판이 천천히 돌아오게 해요. 모든 반복을 마치면 다리를 바꿔요."}]},
  "donkey-kick": {"name": "동키 킥", "instructions": [{"title": "준비", "text": "손은 어깨 아래, 무릎은 엉덩이 아래에 두고 네발 자세를 취해요. 코어에 힘을 줘요."}, {"title": "차올리기", "text": "무릎을 90°로 굽힌 채 허벅지가 등과 일직선이 될 때까지 한 발을 천장 쪽으로 밀어 올려요."}, {"title": "내리기", "text": "무릎이 바닥에 닿지 않게 내리고 허리를 젖히지 마세요. 세트가 끝나면 다리를 바꿔요."}]},
  "fire-hydrant": {"name": "파이어 하이드런트", "instructions": [{"title": "준비", "text": "손은 어깨 아래, 무릎은 엉덩이 아래에 두고 네발 자세를 취해요. 코어에 힘을 줘요."}, {"title": "들어 올리기", "text": "무릎을 굽힌 채 허벅지가 엉덩이 높이와 비슷해질 때까지 한쪽 다리를 옆으로 들어 올려요."}, {"title": "내리기", "text": "체중을 옮기거나 몸통을 돌리지 말고 천천히 내려요. 세트가 끝나면 다리를 바꿔요."}]},
  "curtsy-lunge": {"name": "커트시 런지", "instructions": [{"title": "서기", "text": "발을 골반 너비로 벌리고 양손에 덤벨을 들어 몸 옆에 둔 채 똑바로 서요."}, {"title": "뒤로 교차", "text": "커트시 인사를 하듯 한 다리를 다른 다리 뒤 대각선으로 빼고, 앞 허벅지가 거의 평행이 될 때까지 내려가요."}, {"title": "돌아오기", "text": "앞무릎을 발끝 방향에 맞춘 채 앞발 뒤꿈치로 밀어 시작 자세로 돌아와요. 다리를 번갈아 해요."}]},
  "lateral-lunge": {"name": "사이드 런지", "instructions": [{"title": "서기", "text": "발을 모으고 서서 양손에 덤벨을 들거나 덤벨 하나를 가슴 앞에 들어요."}, {"title": "옆으로 딛기", "text": "옆으로 크게 한 걸음 내딛고 그 다리 쪽으로 엉덩이를 뒤로 빼며 앉아요. 반대쪽 다리는 곧게 펴고 양발은 바닥에 붙여요."}, {"title": "돌아오기", "text": "굽힌 다리로 밀어 시작 자세로 돌아와요. 좌우를 번갈아 하거나 한쪽을 먼저 끝내요."}]},
  "hip-abduction-machine": {"name": "힙 어브덕션 머신", "instructions": [{"title": "준비", "text": "등을 패드에 대고 앉아 허벅지 패드를 무릎 바깥쪽에 대요."}, {"title": "벌리기", "text": "둔근 옆쪽을 조여 무릎을 최대한 벌리고 잠깐 유지해요."}, {"title": "돌아오기", "text": "중량판이 닿지 않게 하면서 다리를 천천히 다시 모아요."}]},
  "hip-adduction-machine": {"name": "힙 어덕션 머신", "instructions": [{"title": "준비", "text": "등을 패드에 대고 앉아 허벅지 패드를 무릎 안쪽에 대요. 통제할 수 있는 스트레칭 범위에서 시작해요."}, {"title": "모으기", "text": "등을 패드에 붙인 채 패드가 맞닿을 때까지 무릎을 모아요."}, {"title": "돌아오기", "text": "무게를 내려놓지 말고 다리를 천천히 벌려 시작 자세로 돌아와요."}]},
  "copenhagen-plank": {"name": "코펜하겐 플랭크", "instructions": [{"title": "준비", "text": "벤치 옆에 옆으로 누워 전완을 어깨 아래에 두고, 위쪽 다리의 무릎이나 발목 안쪽을 벤치에 올려요."}, {"title": "들어 올리기", "text": "위쪽 다리로 벤치를 누르며 몸이 일직선이 될 때까지 엉덩이를 들어 올려요. 아래쪽 다리는 자유롭게 늘어뜨려요."}, {"title": "버티기", "text": "엉덩이를 높게 유지하고 정해진 시간 동안 호흡을 일정하게 해요. 그다음 반대쪽도 같은 시간 동안 해요."}]},
  "seated-calf-raise": {"name": "시티드 카프 레이즈", "instructions": [{"title": "준비", "text": "발 앞꿈치를 발판 끝에 올리고 무릎 패드를 무릎 위 허벅지에 밀착해 앉아요."}, {"title": "올리기", "text": "안전 장치를 풀고 발끝으로 최대한 높이 밀어 올려요. 맨 위에서 잠깐 멈춰요."}, {"title": "내리기", "text": "튕기지 말고 발뒤꿈치를 발판 아래로 천천히 내려 충분히 늘려요."}]},
  "leg-press-calf-raise": {"name": "레그 프레스 카프 레이즈", "instructions": [{"title": "준비", "text": "레그 프레스에 앉아 발 앞꿈치를 발판 아래쪽 끝에 올리고 뒤꿈치는 띄워요. 다리는 펴되 무릎은 잠그지 마세요."}, {"title": "밀기", "text": "무릎을 굽히지 말고 발끝을 최대한 뻗어 발판을 밀어내요."}, {"title": "돌아오기", "text": "종아리가 충분히 늘어날 때까지 발판이 천천히 돌아오게 해요. 발은 발판 끝에 단단히 붙여요."}]},
  "smith-calf-raise": {"name": "스미스 머신 카프 레이즈", "instructions": [{"title": "준비", "text": "스미스 바 아래 스텝이나 원판 위에 서서 바를 등 상부에 얹고 발 앞꿈치를 가장자리에 둬요."}, {"title": "올리기", "text": "바를 고리에서 빼고 다리를 편 채 발끝으로 최대한 높이 밀어 올려요. 맨 위에서 잠깐 멈춰요."}, {"title": "내리기", "text": "발뒤꿈치를 가장자리 아래로 천천히 내려 충분히 늘려요. 마지막 반복 후 바를 다시 걸어요."}]},
  "single-leg-calf-raise": {"name": "싱글 레그 카프 레이즈", "instructions": [{"title": "자세 잡기", "text": "한 발로 서서 발 앞꿈치를 스텝 가장자리에 올려요. 원하면 같은 쪽 손에 덤벨을 들고, 다른 손으로는 지지대를 잡아요."}, {"title": "올리기", "text": "다리를 편 채 발끝으로 최대한 높이 밀어 올리고 잠깐 멈춰요."}, {"title": "내리기", "text": "발뒤꿈치를 스텝 아래로 천천히 내려 충분히 늘려요. 모든 반복을 마치면 다리를 바꿔요."}]},
  "tibialis-raise": {"name": "티비알리스 레이즈", "instructions": [{"title": "준비", "text": "벽에 등을 기대고 다리를 편 채 발뒤꿈치를 약 30cm 앞에 둬요."}, {"title": "들어 올리기", "text": "발뒤꿈치를 바닥에 붙인 채 발끝을 정강이 쪽으로 최대한 높이 당겨요."}, {"title": "내리기", "text": "발끝이 바닥에 거의 닿을 때까지 천천히 내린 뒤 바로 다음 반복으로 이어가요."}]},
  "treadmill": {"name": "러닝머신", "instructions": [{"title": "준비", "text": "양옆 발판에 발을 올리고 서서 안전 키를 옷에 끼운 뒤 느린 속도로 시작해요."}, {"title": "동작", "text": "벨트 가운데에서 몸을 세우고 팔에 힘을 뺀 채 걷거나 달려요. 손잡이는 타고 내릴 때만 잡아요."}, {"title": "페이스", "text": "유지할 수 있는 속도와 경사를 선택해요. 워밍업이라면 완전한 문장으로 말할 수 있을 정도여야 해요."}]},
  "elliptical": {"name": "일립티컬", "instructions": [{"title": "준비", "text": "페달에 올라 움직이는 손잡이를 잡고, 부드럽게 움직일 수 있는 저항을 선택해요."}, {"title": "동작", "text": "걸음에 맞춰 손잡이를 밀고 당겨요. 발 전체를 페달에 붙이고 상체는 세워요."}, {"title": "페이스", "text": "일정하고 고른 리듬을 유지해요. 워밍업이라면 편하게 대화할 수 있을 정도여야 해요."}]},
  "exercise-bike": {"name": "실내 자전거", "instructions": [{"title": "준비", "text": "페달이 가장 아래에 있을 때 무릎이 살짝 굽혀지도록 안장을 조절해요. 낮은 저항으로 시작해요."}, {"title": "페달 밟기", "text": "상체는 고정하고 발 앞꿈치를 페달에 올린 채 부드럽게 원을 그리며 페달을 밟아요."}, {"title": "페이스", "text": "일정한 케이던스를 유지하고 목표에 맞게 저항을 설정해요. 워밍업이라면 대화할 수 있을 정도여야 해요."}]},
  "rowing-machine": {"name": "로잉 머신", "instructions": [{"title": "준비", "text": "스트랩이 발의 가장 넓은 부분을 지나도록 발을 고정해요. 댐퍼는 3~5 정도의 중간 단계로 설정해요."}, {"title": "스트로크", "text": "먼저 다리로 밀고, 상체를 살짝 뒤로 젖히며 손잡이를 아래쪽 갈비뼈로 당겨요. 돌아올 때는 팔, 상체, 다리 순으로 반대로 움직여요."}, {"title": "페이스", "text": "돌아오는 시간을 당기는 시간의 약 두 배로 하고, 가벼운 운동이라면 분당 20~24회 정도로 일정한 스트로크 속도를 유지해요."}]},
  "stair-climber": {"name": "천국의 계단", "instructions": [{"title": "준비", "text": "계단에 올라 옆 손잡이를 가볍게 잡고 느린 속도로 시작해요."}, {"title": "오르기", "text": "각 계단에 발 전체를 올리고 몸을 곧게 세워요. 손잡이에 기대거나 매달리지 마세요."}, {"title": "페이스", "text": "좋은 자세를 유지할 수 있는 만큼만 속도를 올려요. 워밍업이라면 대화할 수 있을 정도여야 해요."}]},
  "air-bike": {"name": "에어 바이크", "instructions": [{"title": "준비", "text": "페달이 가장 아래에 있을 때 무릎이 살짝 굽혀지도록 안장을 조절하고, 움직이는 손잡이를 잡아요."}, {"title": "동작", "text": "페달을 밟으며 손잡이를 밀고 당겨 팔과 다리를 함께 써요. 세게 할수록 저항이 높아져요."}, {"title": "페이스", "text": "가볍게 시작해 점점 강도를 높여요. 인터벌이라면 운동 구간에서는 전력을 다하고, 이후 호흡이 안정될 때까지 천천히 페달을 밟아요."}]}
}$ko$::jsonb) as v (key, value)
where e.id = v.key;
